    census.push_str("];\n");
    fs::write(out.join("reference-source-census.rs"), census).expect("write compile-time census");
}

//! Bounded, versioned identities for artifact plumbing.
//!
//! This module does not hash by implementing SHA-256: RustCrypto `sha2` owns
//! that operation. The course owns the framing, schema and validation.
//! V1 is compact UTF-8 JSON followed by exactly one LF. Object keys are sorted
//! by UTF-8 bytes; all values in `fields` are strings, not JSON numbers.

use std::collections::BTreeMap;
use std::fmt;

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

pub const IDENTITY_SCHEMA_VERSION: u32 = 1;
pub const MAX_DOMAIN_BYTES: usize = 64;
pub const MAX_KEY_BYTES: usize = 64;
pub const MAX_FIELDS: usize = 128;
pub const MAX_VALUE_BYTES: usize = 65_536;
pub const MAX_INPUT_BYTES: usize = 262_144;
pub const MAX_ENCODED_BYTES: usize = 2_097_152;

/// Immutable identity fields; a caller still owns domain-specific requirements.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ArtifactIdentity {
    domain: String,
    fields: BTreeMap<String, String>,
}

/// Exact digest bytes and their library-produced lowercase hexadecimal spelling.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ArtifactDigest {
    bytes: [u8; 32],
    hex: String,
}

impl ArtifactDigest {
    pub fn as_bytes(&self) -> &[u8; 32] {
        &self.bytes
    }

    pub fn as_hex(&self) -> &str {
        &self.hex
    }
}

impl fmt::Display for ArtifactDigest {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.hex)
    }
}

/// Hash already available bytes. Input acquisition/budgeting belongs to its owner.
pub fn sha256(bytes: &[u8]) -> ArtifactDigest {
    let output = Sha256::digest(bytes);
    let hex = format!("{output:x}");
    ArtifactDigest {
        bytes: output.into(),
        hex,
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum IdentityError {
    InvalidDomain,
    InvalidKey,
    EmptyFields,
    TooManyFields,
    DuplicateField,
    ValueTooLarge,
    InputTooLarge,
    EncodedTooLarge,
    InvalidJson,
    UnsupportedSchema,
    NonCanonical,
    Serialization,
}

impl fmt::Display for IdentityError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let message = match self {
            Self::InvalidDomain => {
                "identity domain must be 1..64 ASCII bytes with a lowercase initial letter"
            }
            Self::InvalidKey => {
                "identity key must be 1..64 ASCII bytes with a lowercase initial letter"
            }
            Self::EmptyFields => "identity must contain at least one field",
            Self::TooManyFields => "identity exceeds 128 fields",
            Self::DuplicateField => "identity contains a duplicate field",
            Self::ValueTooLarge => "identity field exceeds 65536 UTF-8 bytes",
            Self::InputTooLarge => "identity domain, keys and values exceed 262144 UTF-8 bytes",
            Self::EncodedTooLarge => "encoded identity exceeds 2097152 bytes",
            Self::InvalidJson => "identity is not a valid v1 JSON record",
            Self::UnsupportedSchema => "unsupported identity schema version",
            Self::NonCanonical => "identity bytes are not the exact canonical v1 encoding",
            Self::Serialization => "identity serialization failed",
        };
        f.write_str(message)
    }
}

impl std::error::Error for IdentityError {}

#[derive(Serialize)]
struct WireIdentity<'a> {
    // Declaration order is the frozen UTF-8 key order, not caller field order.
    domain: &'a str,
    fields: &'a BTreeMap<String, String>,
    schema_version: u32,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct OwnedWireIdentity {
    domain: String,
    fields: BTreeMap<String, String>,
    schema_version: u32,
}

fn valid_identifier(value: &str, maximum: usize) -> bool {
    let bytes = value.as_bytes();
    !bytes.is_empty()
        && bytes.len() <= maximum
        && bytes[0].is_ascii_lowercase()
        && bytes.iter().all(|b| {
            b.is_ascii_lowercase() || b.is_ascii_digit() || matches!(*b, b'.' | b'_' | b'-')
        })
}

impl ArtifactIdentity {
    /// Validate before retaining any caller field. Duplicate keys never overwrite.
    /// Values are opaque UTF-8 strings: no trimming or Unicode normalization.
    pub fn new<'a>(
        domain: &str,
        fields: impl IntoIterator<Item = (&'a str, &'a str)>,
    ) -> Result<Self, IdentityError> {
        if !valid_identifier(domain, MAX_DOMAIN_BYTES) {
            return Err(IdentityError::InvalidDomain);
        }
        let mut retained = BTreeMap::new();
        let mut input_bytes = domain.len();
        for (key, value) in fields {
            if retained.len() == MAX_FIELDS {
                return Err(IdentityError::TooManyFields);
            }
            if !valid_identifier(key, MAX_KEY_BYTES) {
                return Err(IdentityError::InvalidKey);
            }
            if retained.contains_key(key) {
                return Err(IdentityError::DuplicateField);
            }
            if value.len() > MAX_VALUE_BYTES {
                return Err(IdentityError::ValueTooLarge);
            }
            input_bytes = input_bytes
                .checked_add(key.len())
                .and_then(|n| n.checked_add(value.len()))
                .ok_or(IdentityError::InputTooLarge)?;
            if input_bytes > MAX_INPUT_BYTES {
                return Err(IdentityError::InputTooLarge);
            }
            retained.insert(key.to_owned(), value.to_owned());
        }
        if retained.is_empty() {
            return Err(IdentityError::EmptyFields);
        }
        Ok(Self {
            domain: domain.to_owned(),
            fields: retained,
        })
    }

    pub fn domain(&self) -> &str {
        &self.domain
    }

    pub fn fields(&self) -> &BTreeMap<String, String> {
        &self.fields
    }

    pub fn canonical_bytes(&self) -> Result<Vec<u8>, IdentityError> {
        let mut bytes = serde_json::to_vec(&WireIdentity {
            domain: &self.domain,
            fields: &self.fields,
            schema_version: IDENTITY_SCHEMA_VERSION,
        })
        .map_err(|_| IdentityError::Serialization)?;
        bytes.push(b'\n');
        if bytes.len() > MAX_ENCODED_BYTES {
            return Err(IdentityError::EncodedTooLarge);
        }
        Ok(bytes)
    }

    /// Accept only exact v1 bytes, not semantically similar JSON or last-key-wins.
    /// The encoded-byte bound is applied before parsing any untrusted input.
    pub fn from_canonical_bytes(bytes: &[u8]) -> Result<Self, IdentityError> {
        if bytes.len() > MAX_ENCODED_BYTES {
            return Err(IdentityError::EncodedTooLarge);
        }
        let wire: OwnedWireIdentity =
            serde_json::from_slice(bytes).map_err(|_| IdentityError::InvalidJson)?;
        if wire.schema_version != IDENTITY_SCHEMA_VERSION {
            return Err(IdentityError::UnsupportedSchema);
        }
        let identity = Self::new(
            &wire.domain,
            wire.fields
                .iter()
                .map(|(key, value)| (key.as_str(), value.as_str())),
        )?;
        if identity.canonical_bytes()? != bytes {
            return Err(IdentityError::NonCanonical);
        }
        Ok(identity)
    }

    pub fn digest(&self) -> Result<ArtifactDigest, IdentityError> {
        Ok(sha256(&self.canonical_bytes()?))
    }
}

// Reference-source provenance plumbing, not a taught LLM transformation.
// JSON syntax is serde_json's responsibility; closed schemas and provenance
// checks below are course-owned. No filesystem or checkpoint I/O occurs here.
// Only the forty course-owned reference source files are bound. Dependencies,
// toolchain and runtime compatibility are separate execution evidence: equal
// source identities do not establish cross-environment bitwise equivalence.

use std::collections::BTreeMap;
use std::fmt;

use serde::de::{self, MapAccess, Visitor};
use serde::{Deserialize, Deserializer, Serialize};

use crate::artifact_identity::{ArtifactDigest, ArtifactIdentity, sha256};

include!(concat!(env!("OUT_DIR"), "/reference-source-census.rs"));

pub const MAX_MANIFEST_BYTES: usize = 32_768;
pub const MAX_FILE_COUNT: usize = 64;
pub const MAX_SOURCE_BYTES: usize = 1_048_576;
pub const MAX_TOTAL_BYTES: usize = 4_194_304;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ReferenceSourceError {
    Oversize,
    InvalidJson,
    UnsupportedSchema,
    InvalidPath,
    InvalidHash,
    NonCanonical,
    UnapprovedManifest,
    DuplicatePath,
    Coverage,
    SourceDrift,
    Identity,
}

impl fmt::Display for ReferenceSourceError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "reference source verification failed: {self:?}")
    }
}

impl std::error::Error for ReferenceSourceError {}

// Maps need an explicit duplicate rejection: a BTreeMap serde default would
// otherwise silently replace an earlier value. Top-level duplicates/unknown
// fields are rejected by serde's derived closed struct visitor.
fn unique_map<'de, D>(deserializer: D) -> Result<BTreeMap<String, String>, D::Error>
where
    D: Deserializer<'de>,
{
    struct UniqueMap;
    impl<'de> Visitor<'de> for UniqueMap {
        type Value = BTreeMap<String, String>;
        fn expecting(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
            formatter.write_str("a bounded map with unique string keys")
        }
        fn visit_map<A>(self, mut access: A) -> Result<Self::Value, A::Error>
        where
            A: MapAccess<'de>,
        {
            let mut map = BTreeMap::new();
            while let Some((key, value)) = access.next_entry::<String, String>()? {
                if map.len() >= MAX_FILE_COUNT || map.insert(key, value).is_some() {
                    return Err(de::Error::custom("duplicate or oversized source map"));
                }
            }
            Ok(map)
        }
    }
    deserializer.deserialize_map(UniqueMap)
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct Manifest {
    // Declaration order is canonical UTF-8 object-key order.
    #[serde(deserialize_with = "unique_map")]
    dependency_hashes: BTreeMap<String, String>,
    domain: String,
    schema: u32,
    #[serde(deserialize_with = "unique_map")]
    source_hashes: BTreeMap<String, String>,
    source_revision: String,
}

/// Only this module can construct the proof. Matching a caller's revision string
/// is insufficient: both the approved manifest and actual compiled source bytes
/// must match the complete supplied census.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReferenceSourceProof {
    source_revision: String,
    identity: ArtifactIdentity,
    digest: ArtifactDigest,
}

impl ReferenceSourceProof {
    pub fn source_revision(&self) -> &str {
        &self.source_revision
    }
    pub fn identity(&self) -> &ArtifactIdentity {
        &self.identity
    }
    pub fn digest(&self) -> &ArtifactDigest {
        &self.digest
    }
}

fn lower_hex(value: &str, length: usize) -> bool {
    value.len() == length
        && value
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

fn safe_path(path: &str) -> bool {
    !path.is_empty()
        && path.is_ascii()
        && !path.starts_with('/')
        && path.split('/').all(|component| {
            !component.is_empty()
                && component != "."
                && component != ".."
                && component
                    .bytes()
                    .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.'))
        })
}

pub fn verify_reference_source(
    manifest_bytes: &[u8],
    supplied_files: &[(&str, &[u8])],
) -> Result<ReferenceSourceProof, ReferenceSourceError> {
    if manifest_bytes.len() > MAX_MANIFEST_BYTES || supplied_files.len() > MAX_FILE_COUNT {
        return Err(ReferenceSourceError::Oversize);
    }
    let manifest: Manifest =
        serde_json::from_slice(manifest_bytes).map_err(|_| ReferenceSourceError::InvalidJson)?;
    if manifest.schema != 1 || manifest.domain != "functional-reference-source" {
        return Err(ReferenceSourceError::UnsupportedSchema);
    }
    if !manifest.dependency_hashes.is_empty() || manifest.source_hashes.len() != 40 {
        return Err(ReferenceSourceError::Coverage);
    }
    if !lower_hex(&manifest.source_revision, 40) {
        return Err(ReferenceSourceError::InvalidHash);
    }
    let mut expected = BTreeMap::new();
    for (path, hash) in manifest
        .source_hashes
        .iter()
        .chain(manifest.dependency_hashes.iter())
    {
        if !safe_path(path) {
            return Err(ReferenceSourceError::InvalidPath);
        }
        if !lower_hex(hash, 64) {
            return Err(ReferenceSourceError::InvalidHash);
        }
        if expected.insert(path.as_str(), hash.as_str()).is_some() {
            return Err(ReferenceSourceError::DuplicatePath);
        }
    }
    let mut canonical =
        serde_json::to_vec(&manifest).map_err(|_| ReferenceSourceError::InvalidJson)?;
    canonical.push(b'\n');
    if canonical != manifest_bytes {
        return Err(ReferenceSourceError::NonCanonical);
    }
    if manifest_bytes != COMPILED_MANIFEST {
        return Err(ReferenceSourceError::UnapprovedManifest);
    }
    if expected.len() != COMPILED_FILES.len() || supplied_files.len() != expected.len() {
        return Err(ReferenceSourceError::Coverage);
    }
    let mut supplied = BTreeMap::new();
    let mut total = 0usize;
    for &(path, bytes) in supplied_files {
        if !safe_path(path) {
            return Err(ReferenceSourceError::InvalidPath);
        }
        if bytes.len() > MAX_SOURCE_BYTES {
            return Err(ReferenceSourceError::Oversize);
        }
        total = total
            .checked_add(bytes.len())
            .ok_or(ReferenceSourceError::Oversize)?;
        if total > MAX_TOTAL_BYTES {
            return Err(ReferenceSourceError::Oversize);
        }
        if supplied.insert(path, bytes).is_some() {
            return Err(ReferenceSourceError::DuplicatePath);
        }
    }
    for &(path, compiled) in COMPILED_FILES {
        let bytes = supplied.get(path).ok_or(ReferenceSourceError::Coverage)?;
        let hash = expected.get(path).ok_or(ReferenceSourceError::Coverage)?;
        // Hash actual bytes on both sides, including the build-time census.
        if sha256(bytes).as_hex() != *hash || sha256(compiled).as_hex() != *hash {
            return Err(ReferenceSourceError::SourceDrift);
        }
    }
    let manifest_hash = sha256(manifest_bytes);
    let identity = ArtifactIdentity::new(
        "functional_reference_source",
        [
            ("manifest_sha256", manifest_hash.as_hex()),
            ("schema", "1"),
            ("source_revision", manifest.source_revision.as_str()),
        ],
    )
    .map_err(|_| ReferenceSourceError::Identity)?;
    let digest = identity
        .digest()
        .map_err(|_| ReferenceSourceError::Identity)?;
    Ok(ReferenceSourceProof {
        source_revision: manifest.source_revision,
        identity,
        digest,
    })
}

/// Verify the actual compiler-bound reference bytes without a per-caller loader.
/// This is source provenance, not live Git cleanliness or evidence of model quality.
/// It is not a dependency, toolchain or runtime-equivalence proof.
/// The same approved-manifest/hash/coverage checks apply to the compiled census.
pub fn verify_compiled_reference_source() -> Result<ReferenceSourceProof, ReferenceSourceError> {
    verify_reference_source(COMPILED_MANIFEST, COMPILED_FILES)
}

use std::fs;
use std::path::PathBuf;

use llm_from_scratch_practical::artifact_identity::sha256;
use llm_from_scratch_practical::reference_source_identity::{
    MAX_MANIFEST_BYTES, ReferenceSourceError, verify_compiled_reference_source,
    verify_reference_source,
};

#[allow(dead_code)]
#[path = "../build.rs"]
mod registry;

fn repository() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(3)
        .unwrap()
        .to_path_buf()
}

fn inputs() -> (Vec<u8>, Vec<(&'static str, Vec<u8>)>) {
    let root = repository();
    (
        fs::read(root.join("configs/practical-reference-source-v1.json")).unwrap(),
        registry::SOURCE_CENSUS
            .iter()
            .map(|&path| (path, fs::read(root.join(path)).unwrap()))
            .collect(),
    )
}

fn verify(manifest: &[u8], files: &[(&str, Vec<u8>)]) -> Result<(), ReferenceSourceError> {
    verify_reference_source(
        manifest,
        &files
            .iter()
            .map(|(p, b)| (*p, b.as_slice()))
            .collect::<Vec<_>>(),
    )
    .map(|_| ())
}

#[test]
fn exact_compiled_reference_produces_an_immutable_identity() {
    let (manifest, files) = inputs();
    let borrowed = files
        .iter()
        .map(|(p, b)| (*p, b.as_slice()))
        .collect::<Vec<_>>();
    let proof = verify_reference_source(&manifest, &borrowed).unwrap();
    assert_eq!(
        proof.source_revision(),
        "9f38a060903c472c4d571efd8e52da1f17e553ff"
    );
    assert_eq!(proof.identity().domain(), "functional_reference_source");
    assert_eq!(proof.identity().digest().unwrap(), *proof.digest());
    assert_eq!(proof, verify_compiled_reference_source().unwrap());
    assert_eq!(
        proof.identity().fields()["manifest_sha256"],
        sha256(&manifest).as_hex()
    );
}

#[test]
fn missing_extra_duplicate_or_stale_bytes_never_produce_proof() {
    let (manifest, mut files) = inputs();
    let last = files.pop().unwrap();
    assert_eq!(
        verify(&manifest, &files),
        Err(ReferenceSourceError::Coverage)
    );
    files.push(last.clone());
    files.push(last);
    assert!(verify(&manifest, &files).is_err());
    files.pop();
    files[1] = files[0].clone();
    assert_eq!(
        verify(&manifest, &files),
        Err(ReferenceSourceError::DuplicatePath)
    );
    let (_, mut files) = inputs();
    files[0].1.push(b' ');
    assert_eq!(
        verify(&manifest, &files),
        Err(ReferenceSourceError::SourceDrift)
    );
    files[0].0 = "unexpected.rs";
    assert_eq!(
        verify(&manifest, &files),
        Err(ReferenceSourceError::Coverage)
    );
}

#[test]
fn caller_revision_or_rewritten_hashes_cannot_rebind_the_baseline() {
    let (manifest, files) = inputs();
    let source = String::from_utf8(manifest).unwrap();
    let changed = source.replace("9f38a060903c472c4d571efd8e52da1f17e553ff", &"0".repeat(40));
    assert_eq!(
        verify(changed.as_bytes(), &files),
        Err(ReferenceSourceError::UnapprovedManifest)
    );
}

#[test]
fn duplicate_unknown_noncanonical_and_oversized_json_are_rejected() {
    let (manifest, files) = inputs();
    let source = String::from_utf8(manifest).unwrap();
    for bad in [
        source.replacen("{", "{\"schema\":1,", 1),
        source.replacen("{", "{\"unknown\":0,", 1),
        source.replacen(
            "\"sourceHashes\":{",
            "\"sourceHashes\":{\"duplicate\":\"x\",\"duplicate\":\"x\",",
            1,
        ),
        source.replacen("\"schema\":1", "\"schema\":2", 1),
        source.replacen(
            "\"domain\":\"functional-reference-source\"",
            "\"domain\":\"other\"",
            1,
        ),
        source.replace("rust/crates/llm-from-scratch/src/lib.rs", "../lib.rs"),
        source.replace("9f38a06", "9F38A06"),
        source.trim_end().to_owned(),
        format!(" {source}"),
    ] {
        assert!(verify(bad.as_bytes(), &files).is_err(), "accepted {bad}");
    }
    assert_eq!(
        verify(&vec![b' '; MAX_MANIFEST_BYTES + 1], &files),
        Err(ReferenceSourceError::Oversize)
    );
}

#[test]
fn complete_original_lib_and_course_source_only_census_remain_exact() {
    let bytes = fs::read(repository().join("rust/crates/llm-from-scratch/src/lib.rs")).unwrap();
    assert_eq!(
        sha256(&bytes).as_hex(),
        "e28fb34befb4a2539e2b932efc6bdd5022091810f080f1e57d22cb654b8e7c67"
    );
    assert!(registry::SOURCE_CENSUS.contains(&"rust/crates/llm-from-scratch/src/lib.rs"));
    assert!(
        !registry::SOURCE_CENSUS.contains(&"rust/crates/llm-from-scratch/src/artifact_identity.rs")
    );
    assert_eq!(registry::SOURCE_CENSUS.len(), 40);
    assert!(
        registry::SOURCE_CENSUS
            .iter()
            .all(|path| path.ends_with(".rs"))
    );
    let manifest: serde_json::Value = serde_json::from_slice(&inputs().0).unwrap();
    assert_eq!(manifest["dependencyHashes"], serde_json::json!({}));
    let mut changed = manifest;
    changed["dependencyHashes"] = serde_json::json!({"Cargo.lock": "0".repeat(64)});
    let mut changed_bytes = serde_json::to_vec(&changed).unwrap();
    changed_bytes.push(b'\n');
    assert_eq!(
        verify(&changed_bytes, &inputs().1),
        Err(ReferenceSourceError::Coverage)
    );
}

