const LLM_EVOLUTION_REQUIRED_FROM_ORDER = 10;
const LLM_EVOLUTION_CORRECTIVE_ORDERS = new Set([8, 9]);
const LLM_PREDECESSOR_KINDS = new Set([
  'language-model',
  'neural-architecture',
  'model-building-practice',
  'training-practice',
  'evaluation-method',
  'inference-design',
]);
const LLM_SOURCE_ROLES = new Set(['earlier', 'later']);
const LEARNER_BUILD_META_PATTERNS = Object.freeze([
  {
    label: 'build or authoring instructions',
    pattern: /\b(?:build|authoring|content) (?:instruction|contract|requirement|rule)s?\b/i,
  },
