  },
]);

export class ContentValidationError extends Error {
  constructor(issues, heading = 'Content validation failed') {
    super(heading + ':\n- ' + issues.join('\n- '));
    this.name = 'ContentValidationError';
    this.issues = issues;
  }
}

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function hasText(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function isOrientationChapter(data) {
  return data?.chapter_kind === 'orientation';
}

function isPracticalCourse(course) {
  return course?.id === PRACTICAL_COURSE_ID;
}

function chapterSections(data, course) {
  if (!isOrientationChapter(data)) return REQUIRED_CHAPTER_SECTIONS;
  return isPracticalCourse(course)
    ? PRACTICAL_ORIENTATION_CHAPTER_SECTIONS
    : ORIENTATION_CHAPTER_SECTIONS;
}

function addTextIssue(issues, value, field, sourceName) {
  if (!hasText(value)) {
    issues.push(sourceName + ': ' + field + ' must be a non-empty string');
  }
}

function isHttpsUrl(value) {
  if (!hasText(value)) return false;
  try {
    const parsed = new URL(value);
    return (
      parsed.protocol === 'https:' &&
      parsed.username === '' &&
      parsed.password === ''
    );
  } catch {
    return false;
  }
}

function canonicalSourceUrl(value) {
  if (!isHttpsUrl(value)) return null;
  const parsed = new URL(value);
  parsed.hash = '';
  return parsed.href;
}

function requiresLlmEvolution(order, contentRevision, course) {
  return (
    Number.isInteger(order) &&
    ((isPracticalCourse(course) && order >= 1) ||
      order >= LLM_EVOLUTION_REQUIRED_FROM_ORDER ||
      (LLM_EVOLUTION_CORRECTIVE_ORDERS.has(order) && contentRevision >= 2))
  );
}

function validateExactKeys(issues, value, expected, field, sourceName) {
  const actual = Object.keys(value).sort();
  const sortedExpected = [...expected].sort();
  if (JSON.stringify(actual) !== JSON.stringify(sortedExpected)) {
    issues.push(
      sourceName + ': ' + field + ' keys must be exactly ' + sortedExpected.join(', '),
    );
  }
}

function validateLlmEvolution(evolution, issues, sourceName, required, course) {
  if (evolution === undefined) {
    if (required) {
      issues.push(
        isPracticalCourse(course)
          ? sourceName + ': history.llm_evolution is required for every practical lesson'
          : sourceName +
            ': history.llm_evolution is required for revised Chapters 8-9 and from chapter order ' +
            LLM_EVOLUTION_REQUIRED_FROM_ORDER,
      );
    }
    return;
  }
  if (!isObject(evolution)) {
    issues.push(sourceName + ': history.llm_evolution must be an object');
    return;
  }
  validateExactKeys(
    issues,
    evolution,
    ['predecessor_kind', 'limitation', 'later_advance', 'modern_llm_role', 'sources'],
    'history.llm_evolution',
    sourceName,
  );
  if (!LLM_PREDECESSOR_KINDS.has(evolution.predecessor_kind)) {
    issues.push(
      sourceName +
        ': history.llm_evolution.predecessor_kind must be one of ' +
        [...LLM_PREDECESSOR_KINDS].join(', '),
    );
  }
  for (const field of ['limitation', 'later_advance', 'modern_llm_role']) {
    addTextIssue(
      issues,
      evolution[field],
      'history.llm_evolution.' + field,
      sourceName,
    );
  }
  if (!Array.isArray(evolution.sources) || evolution.sources.length < 2) {
    issues.push(
      sourceName + ': history.llm_evolution.sources must contain earlier and later evidence',
    );
    return;
  }
  const roles = new Set();
  const urls = new Set();
  evolution.sources.forEach((source, index) => {
    const field = 'history.llm_evolution.sources[' + index + ']';
    if (!isObject(source)) {
      issues.push(sourceName + ': ' + field + ' must be an object');
      return;
    }
    validateExactKeys(
      issues,
      source,
      ['role', 'year', 'name', 'source_url', 'claim'],
      field,
      sourceName,
    );
    if (!LLM_SOURCE_ROLES.has(source.role)) {
      issues.push(sourceName + ': ' + field + '.role must be earlier or later');
    } else {
      roles.add(source.role);
    }
    if (!Number.isInteger(source.year) || source.year < 1900 || source.year > 9999) {
      issues.push(sourceName + ': ' + field + '.year must be an integer from 1900 to 9999');
    }
    addTextIssue(issues, source.name, field + '.name', sourceName);
    const canonicalUrl = canonicalSourceUrl(source.source_url);
    if (!canonicalUrl) {
      issues.push(sourceName + ': ' + field + '.source_url must be an absolute HTTPS URL');
    } else if (urls.has(canonicalUrl)) {
      issues.push(sourceName + ': duplicate history source URL "' + source.source_url + '"');
    } else {
      urls.add(canonicalUrl);
    }
    addTextIssue(issues, source.claim, field + '.claim', sourceName);
  });
  for (const role of LLM_SOURCE_ROLES) {
    if (!roles.has(role)) {
      issues.push(sourceName + ': history.llm_evolution.sources requires role ' + role);
    }
  }
}

function normalizedRelativePath(value) {
  return typeof value === 'string' ? value.replaceAll('\\', '/') : '';
}

export function isAllowedRustSourcePath(value, course) {
  if (!hasText(value)) {
    return false;
  }

  const normalized = normalizedRelativePath(value);
  return (
    normalized === value &&
    !nodePath.posix.isAbsolute(normalized) &&
    !normalized.split('/').includes('..') &&
    RUST_SOURCE_PATTERN.test(normalized) &&
    (!normalized.startsWith('rust/crates/llm-from-scratch-practical/') ||
      isPracticalCourse(course))
  );
}

export function extractRustRegion(source, region, sourceName = 'Rust source') {
  if (!REGION_PATTERN.test(region)) {
    throw new ContentValidationError([
      sourceName + ': region "' + region + '" must be a lowercase kebab-case identifier',
    ]);
  }

  const lines = source.split(/\r?\n/);
  const startMarker = '// region:' + region;
  const endMarker = '// endregion:' + region;
  const starts = [];
  const ends = [];

  lines.forEach((line, index) => {
    const trimmed = line.trim();
    if (trimmed === startMarker) starts.push(index);
    if (trimmed === endMarker) ends.push(index);
  });

  if (starts.length !== 1 || ends.length !== 1 || starts[0] >= ends[0]) {
    throw new ContentValidationError([
      sourceName + ': expected one ordered ' + startMarker + ' / ' + endMarker + ' pair',
    ]);
  }

  return lines.slice(starts[0] + 1, ends[0]).join('\n');
}

export function parseJsonFrontmatter(source, sourceName = 'document') {
  const normalized = source.replace(/^\uFEFF/, '');
  const match = normalized.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/);

  if (!match) {
    throw new ContentValidationError([
      sourceName +
        ': expected JSON-shaped YAML frontmatter between opening and closing --- lines',
    ]);
  }

  let data;
  try {
    data = JSON.parse(match[1]);
  } catch (error) {
    throw new ContentValidationError([
      sourceName +
        ': frontmatter must be valid JSON (which is also valid YAML): ' +
        error.message,
    ]);
  }

  if (!isObject(data)) {
    throw new ContentValidationError([sourceName + ': frontmatter root must be an object']);
  }

  return {
    data,
    body: normalized.slice(match[0].length),
  };
}

export function extractChapterSectionMarkers(body) {
  return [...body.matchAll(/\{\/\*\s*chapter-section:([a-z-]+)\s*\*\/\}/g)].map(
    (match) => match[1],
  );
}

function maskMdxRange(value) {
  return value.replace(/[^\n]/g, ' ');
}

function maskCodeBlocks(source) {
  const parts = source.split(/(\r?\n)/);
  let fence = null;

  for (let index = 0; index < parts.length; index += 2) {
    const line = parts[index];
    if (fence) {
      const closingCharacter = fence.character === '~' ? '~' : '\\x60';
      const closing = new RegExp(
        '^[ \\t]{0,3}' +
          closingCharacter +
          '{' +
          fence.length +
          ',}[ \\t]*$',
      );
      parts[index] = maskMdxRange(line);
      if (closing.test(line)) fence = null;
      continue;
    }

    const opening = line.match(/^[ \t]{0,3}([\x60~])\1{2,}/);
    if (opening) {
      const run = opening[0].trimStart();
      fence = { character: opening[1], length: run.length };
      parts[index] = maskMdxRange(line);
      continue;
    }

    if (/^(?: {4}|\t)/.test(line)) {
      parts[index] = maskMdxRange(line);
    }
  }

  return parts.join('');
}

export function renderableMdxSource(source) {
  const backtick = String.fromCharCode(96);
  const inlineCode = new RegExp(
    '(' + backtick + '+)([^\\n]*?)\\1',
    'g',
  );

  return maskCodeBlocks(source)
    .replace(/\{\/\*[\s\S]*?\*\/\}/g, maskMdxRange)
    .replace(/<!--[\s\S]*?-->/g, maskMdxRange)
    .replace(/<pre\b[^>]*>[\s\S]*?<\/pre>/gi, maskMdxRange)
    .replace(/<code\b[^>]*>[\s\S]*?<\/code>/gi, maskMdxRange)
    .replace(inlineCode, maskMdxRange);
}

function sliceChapterSections(body) {
  const matches = [...body.matchAll(
    /\{\/\*\s*chapter-section:([a-z-]+)\s*\*\/\}/g,
  )];
  const sections = new Map();
  matches.forEach((match, index) => {
    const end = index + 1 < matches.length ? matches[index + 1].index : body.length;
    sections.set(match[1], body.slice(match.index + match[0].length, end));
  });
  return sections;
}

function visibleSectionEvidence(section) {
  return section
    .replace(/^\s*##[^\n]*$/m, '')
    .replace(/\{\/\*[\s\S]*?\*\/\}/g, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[\`*_#|[\]{}$\\]/g, ' ')
    .replace(/\s+([),.;:!?])/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizedFormula(value) {
  return String(value).replace(/\s+/g, ' ').trim();
}

function directMarkdownLinkDestinations(source) {
  const destinations = [];
  const markdownLinks = /(?<!!)\[[^\]\n]+\]\(\s*(?:<([^>\n]+)>|([^\s)\n]+))(?:\s+["'][^"'\n]*["'])?\s*\)/g;
  for (const match of source.matchAll(markdownLinks)) {
    destinations.push(match[1] ?? match[2]);
  }
  for (const match of source.matchAll(/<(https:\/\/[^>\s]+)>/g)) {
    destinations.push(match[1]);
  }
  return new Set(
    destinations
      .map((destination) => canonicalSourceUrl(destination))
      .filter((destination) => destination !== null),
  );
}

function validateChapterSections(data, body, issues, sourceName, course) {
  const sections = sliceChapterSections(body);
  const requiredSections = chapterSections(data, course);
  for (const name of requiredSections) {
    const section = sections.get(name) ?? '';
    if (!/^\s*##\s+\S/m.test(section)) {
      issues.push(sourceName + ': ' + name + ' section must start with a level-two heading');
    }
    if (visibleSectionEvidence(section).length < 40) {
      issues.push(sourceName + ': ' + name + ' section lacks meaningful teaching evidence');
    }
  }

  const historySection = renderableMdxSource(sections.get('history') ?? '');
  const historyLinks = directMarkdownLinkDestinations(historySection);
  const historyEvidence = visibleSectionEvidence(historySection);
  const llmEvolution = data.history?.llm_evolution;
  const requiredHistoryClaims = llmEvolution
    ? [
        ['limitation', llmEvolution.limitation],
        ['later_advance', llmEvolution.later_advance],
        ['modern_llm_role', llmEvolution.modern_llm_role],
        ...llmEvolution.sources.map((source, index) => [
          'sources[' + index + '].claim',
          source.claim,
        ]),
      ]
    : [];
  for (const [field, claim] of requiredHistoryClaims) {
    const expected = visibleSectionEvidence(claim);
    if (!expected || !historyEvidence.includes(expected)) {
      issues.push(
        sourceName +
          ': history section must render history.llm_evolution.' +
          field +
          ' as visible prose',
      );
    }
  }
  for (const source of llmEvolution?.sources ?? []) {
    if (!historyLinks.has(canonicalSourceUrl(source.source_url))) {
      issues.push(
        sourceName +
          ': history section must cite declared LLM-evolution source ' +
          source.source_url,
      );
    }
  }

  if (!isOrientationChapter(data)) {
    const formulaSection = renderableMdxSource(sections.get('formula') ?? '');
    const displayedFormulae = [...formulaSection.matchAll(/\$\$\s*([\s\S]*?)\s*\$\$/g)].map(
      (match) => normalizedFormula(match[1]),
    );
    if (!displayedFormulae.includes(normalizedFormula(data.formula?.latex))) {
      issues.push(
        sourceName + ': formula section must display formula.latex exactly once as notation',
      );
    } else if (
      displayedFormulae.filter(
        (formula) => formula === normalizedFormula(data.formula?.latex),
      ).length !== 1
    ) {
      issues.push(sourceName + ': formula section must display formula.latex exactly once');
    }

    const rustSection = renderableMdxSource(
      sections.get('rust-implementation') ?? '',
    );
    if (extractRustSourceReferences(rustSection).length === 0) {
      issues.push(sourceName + ': rust-implementation section must contain <RustSource> evidence');
    }
  }

  const visualizationSection = renderableMdxSource(
    sections.get('visualization') ?? '',
  );
  const diagramInvocation = /<[A-Z][A-Za-z0-9]*Diagram(?:\s|\/|>)/g;
  const visualizationInvocations = visualizationSection.match(diagramInvocation) ?? [];
  const bodyInvocations = renderableMdxSource(body).match(diagramInvocation) ?? [];
  const expectedVisualizationCount =
    data.visualization?.decision === 'useful'
      ? 1 + (data.visualization.supplementary?.length ?? 0)
      : 0;
  if (
    data.visualization?.decision === 'useful' &&
    (visualizationInvocations.length !== expectedVisualizationCount ||
      bodyInvocations.length !== expectedVisualizationCount)
  ) {
    issues.push(
      sourceName +
        ': useful visualization must be invoked inside its section; exactly ' +
        expectedVisualizationCount +
        ' *Diagram component invocation(s) are required in the complete body',
    );
  }
  if (
    data.visualization?.decision === 'not-useful' &&
    bodyInvocations.length !== 0
  ) {
    issues.push(sourceName + ': not-useful visualization must not invoke a diagram');
  }

  if (!isOrientationChapter(data)) {
    const exercises = renderableMdxSource(sections.get('exercises') ?? '');
    const answerStart = exercises.indexOf('<details');
    const predictionPrompts =
      answerStart === -1 ? exercises : exercises.slice(0, answerStart);
    const checkedAnswers = answerStart === -1 ? '' : exercises.slice(answerStart);
    const predictionCount = [...predictionPrompts.matchAll(/^\s*\d+\.\s+\S/gm)].length;
    if (!/^\s*1\.\s+\S/m.test(predictionPrompts)) {
      issues.push(sourceName + ': exercises section must contain an ordered practice-task list');
    }
    const answerBlock = checkedAnswers.match(
      /^<details\b[^>]*>\s*<summary\b[^>]*>\s*\S[\s\S]*?<\/summary>([\s\S]*?)<\/details>/,
    );
    if (!answerBlock) {
      issues.push(sourceName + ': exercises section must contain checked answers in <details>');
    } else {
      const answerCount = [...answerBlock[1].matchAll(/^\s*\d+\.\s+\S/gm)].length;
      if (
        visibleSectionEvidence(answerBlock[1]).length < 40 ||
        answerCount !== predictionCount
      ) {
        issues.push(
          sourceName +
            ': checked answers must contain one substantive ordered answer per practice task',
        );
      }
    }
  }

  return sections;
}

function literalAttribute(tag, name) {
  const patterns = [
    new RegExp('(?:^|\\s)' + name + '\\s*=\\s*"([^"]*)"'),
    new RegExp("(?:^|\\s)" + name + "\\s*=\\s*'([^']*)'"),
    new RegExp(
      '(?:^|\\s)' + name + '\\s*=\\s*\\{\\s*"([^"]*)"\\s*\\}',
    ),
    new RegExp(
      "(?:^|\\s)" + name + "\\s*=\\s*\\{\\s*'([^']*)'\\s*\\}",
    ),
  ];

  for (const pattern of patterns) {
    const match = tag.match(pattern);
    if (match) return match[1];
  }

  return undefined;
}

export function extractRustSourceReferences(body) {
  return [...body.matchAll(/<RustSource\b[^>]*\/?\s*>/g)].map((match) => ({
    path: literalAttribute(match[0], 'path'),
    region: literalAttribute(match[0], 'region'),
    caption: literalAttribute(match[0], 'caption'),
    label: literalAttribute(match[0], 'label'),
    tag: match[0],
  }));
}

function validateFormula(formula, issues, sourceName) {
  if (!isObject(formula)) {
    issues.push(sourceName + ': formula must be an object');
    return;
  }

  addTextIssue(issues, formula.latex, 'formula.latex', sourceName);
  if (hasText(formula.latex) && LATEX_PROSE_PATTERN.test(formula.latex)) {
    issues.push(
      sourceName +
        ': formula.latex must contain notation only; put localized prose in the symbol glossary',
    );
  }
  if (!Array.isArray(formula.symbols) || formula.symbols.length === 0) {
    issues.push(sourceName + ': formula.symbols must contain at least one symbol');
    return;
  }

  const seen = new Set();
  formula.symbols.forEach((symbol, index) => {
    if (!isObject(symbol)) {
      issues.push(sourceName + ': formula.symbols[' + index + '] must be an object');
      return;
    }
    addTextIssue(
      issues,
      symbol.symbol,
      'formula.symbols[' + index + '].symbol',
      sourceName,
    );
    addTextIssue(
      issues,
      symbol.meaning,
      'formula.symbols[' + index + '].meaning',
      sourceName,
    );
    if (hasText(symbol.symbol) && seen.has(symbol.symbol)) {
      issues.push(sourceName + ': formula symbol "' + symbol.symbol + '" is duplicated');
    }
    seen.add(symbol.symbol);
  });
}

function validateRustSources(rustSources, issues, sourceName, course) {
  if (!Array.isArray(rustSources) || rustSources.length === 0) {
    issues.push(sourceName + ': rust_sources must contain at least one source declaration');
    return;
  }

  const seen = new Set();
  rustSources.forEach((source, index) => {
    if (!isObject(source)) {
      issues.push(sourceName + ': rust_sources[' + index + '] must be an object');
      return;
    }

    if (!isAllowedRustSourcePath(source.path, course)) {
      issues.push(
        sourceName +
          ': rust_sources[' +
          index +
          '].path must be a repository-relative .rs file under rust/crates/llm-from-scratch/src or rust/demos/<name>/src',
      );
    }
    if (source.region !== undefined && !REGION_PATTERN.test(source.region)) {
      issues.push(
        sourceName +
          ': rust_sources[' +
          index +
          '].region must be a lowercase kebab-case identifier',
      );
    }
    addTextIssue(
      issues,
      source.purpose,
      'rust_sources[' + index + '].purpose',
      sourceName,
    );

    const identity = (source.path ?? '') + '#' + (source.region ?? '');
    if (seen.has(identity)) {
      issues.push(sourceName + ': Rust source declaration "' + identity + '" is duplicated');
    }
    seen.add(identity);
  });
}

function validateVisualization(visualization, issues, sourceName) {
  if (!isObject(visualization)) {
    issues.push(sourceName + ': visualization must be an object');
    return;
  }

  if (!['useful', 'not-useful'].includes(visualization.decision)) {
    issues.push(
      sourceName + ': visualization.decision must be "useful" or "not-useful"',
    );
  }
  addTextIssue(
    issues,
    visualization.rationale,
    'visualization.rationale',
    sourceName,
  );

  if (visualization.decision === 'useful') {
    if (!hasText(visualization.id) || !CONCEPT_ID_PATTERN.test(visualization.id)) {
      issues.push(
        sourceName +
          ': a useful visualization requires a lowercase kebab-case visualization.id',
      );
    }
    if (
      visualization.component !== undefined &&
      (!hasText(visualization.component) ||
        !DIAGRAM_COMPONENT_PATTERN.test(visualization.component))
    ) {
      issues.push(
        sourceName + ': visualization.component must name a *Diagram component',
      );
    }
    const supplementary = visualization.supplementary ?? [];
    if (!Array.isArray(supplementary)) {
      issues.push(sourceName + ': visualization.supplementary must be an array when present');
    } else {
      const ids = [visualization.id];
      const components = visualization.component ? [visualization.component] : [];
      supplementary.forEach((entry, index) => {
        if (!isObject(entry)) {
          issues.push(
            sourceName + ': visualization.supplementary[' + index + '] must be an object',
          );
          return;
        }
        if (!hasText(entry.id) || !CONCEPT_ID_PATTERN.test(entry.id)) {
          issues.push(
            sourceName +
              ': visualization.supplementary[' +
              index +
              '].id must be lowercase kebab-case',
          );
        }
        if (
          !hasText(entry.component) ||
          !DIAGRAM_COMPONENT_PATTERN.test(entry.component)
        ) {
          issues.push(
            sourceName +
              ': visualization.supplementary[' +
              index +
              '].component must name a *Diagram component',
          );
        }
        addTextIssue(
          issues,
          entry.rationale,
          'visualization.supplementary[' + index + '].rationale',
          sourceName,
        );
        ids.push(entry.id);
        components.push(entry.component);
      });
      if (new Set(ids).size !== ids.length) {
        issues.push(sourceName + ': visualization IDs must be unique within the chapter');
      }
      if (new Set(components).size !== components.length) {
        issues.push(sourceName + ': visualization components must be unique within the chapter');
      }
    }
  }

  if (visualization.decision === 'not-useful' && visualization.id !== null) {
    issues.push(
      sourceName + ': a not-useful visualization must set visualization.id to null',
    );
  }
  if (
    visualization.decision === 'not-useful' &&
    (visualization.component !== undefined || visualization.supplementary !== undefined)
  ) {
    issues.push(sourceName + ': a not-useful visualization cannot register components');
  }
}

export function validateChapterMetadata(
  data,
  sourceName = 'chapter',
  supportedLocales = SUPPORTED_LOCALES,
  { course } = {},
) {
  const issues = [];
  if (course) {
    supportedLocales = course.activeLocales;
    try {
      validateCourseChapterIdentity(course, data);
    } catch (error) {
      issues.push(sourceName + ': ' + error.message);
    }
  }

  if (!hasText(data.chapter_id) || !CHAPTER_ID_PATTERN.test(data.chapter_id)) {
    issues.push(sourceName + ': chapter_id must match NN-lowercase-kebab-case');
  }
  if (!supportedLocales.includes(data.locale)) {
    issues.push(
      sourceName +
        ': locale must be configured; expected one of ' +
        supportedLocales.join(', '),
    );
  }
  if (!Number.isInteger(data.content_revision) || data.content_revision < 1) {
    issues.push(sourceName + ': content_revision must be a positive integer');
  }
  if (!Number.isInteger(data.order) || data.order < 0) {
    issues.push(sourceName + ': order must be a nonnegative integer');
  }
  if (!hasText(data.concept_id) || !CONCEPT_ID_PATTERN.test(data.concept_id)) {
    issues.push(sourceName + ': concept_id must be lowercase kebab-case');
  }

  const orientation = isOrientationChapter(data);
  const orientationId = course?.orientationChapterId ?? '00-llm-parts';
  if (orientation && (data.chapter_id !== orientationId || data.order !== 0)) {
    issues.push(sourceName + ': only ' + orientationId + ' at order zero may be an orientation');
  }
  if (data.chapter_kind !== undefined && !['lesson', 'orientation'].includes(data.chapter_kind)) {
    issues.push(sourceName + ': chapter_kind must be lesson or orientation when present');
  }

  for (const field of [
    'title',
    'description',
    'objective',
    'worked_inputs',
    'decoder_connection',
  ]) {
    addTextIssue(issues, data[field], field, sourceName);
  }

  if (orientation) {
    if (data.formula !== null) {
      issues.push(sourceName + ': orientation formula must be null');
    }
  } else {
    validateFormula(data.formula, issues, sourceName);
  }

  if (!isObject(data.history)) {
    issues.push(sourceName + ': history must be an object');
  } else {
    validateLlmEvolution(
      data.history.llm_evolution,
      issues,
      sourceName,
      requiresLlmEvolution(data.order, data.content_revision, course),
      course,
    );
    addTextIssue(issues, data.history.approach, 'history.approach', sourceName);
    addTextIssue(issues, data.history.summary, 'history.summary', sourceName);
    if (orientation) {
      if (data.history.rust_source !== null) {
        issues.push(sourceName + ': orientation history.rust_source must be null');
      }
    } else if (!isAllowedRustSourcePath(data.history.rust_source, course)) {
      issues.push(sourceName + ': history.rust_source is not an allowed repository Rust path');
    }
  }

  if (orientation) {
    if (!Array.isArray(data.rust_sources) || data.rust_sources.length !== 0) {
      issues.push(sourceName + ': orientation rust_sources must be an empty array');
    }
  } else {
    validateRustSources(data.rust_sources, issues, sourceName, course);
  }
  validateVisualization(data.visualization, issues, sourceName);
  if (orientation && isPracticalCourse(course)) {
    if (data.visualization?.decision !== 'not-useful' ||
        data.visualization.id !== null || data.visualization.component !== undefined ||
        (data.visualization.supplementary?.length ?? 0) !== 0) {
      issues.push(sourceName + ': practical orientation must have no diagram');
    }
  } else if (orientation) {
    if (
      data.visualization?.decision !== 'useful' ||
      data.visualization.id !== 'llm-system-map' ||
      data.visualization.component !== 'LlmSystemDiagram' ||
      JSON.stringify(data.visualization.supplementary?.map((entry) => entry?.id) ?? []) !==
        JSON.stringify(['llm-parts-map']) ||
      data.visualization.supplementary?.[0]?.component !== 'LlmPartsDiagram'
    ) {
      issues.push(
        sourceName +
          ': the orientation must register llm-system-map and supplementary llm-parts-map',
      );
    }
  }

  if (
    isObject(data.history) &&
    !orientation &&
    Array.isArray(data.rust_sources) &&
    !data.rust_sources.some((source) => source?.path === data.history.rust_source)
  ) {
    issues.push(sourceName + ': history.rust_source must also appear in rust_sources');
  }

  if (issues.length > 0) {
    throw new ContentValidationError(issues);
  }

  return data;
}

function sourceIdentity(source) {
  return source.path + '#' + (source.region ?? '');
}

function validateFileLocation(data, filePath, issues, supportedLocales, course) {
  const normalized = normalizedRelativePath(filePath);
  const directory = nodePath.posix.basename(course?.contentDirectory ?? 'chapters');
  const match = normalized.match(new RegExp('/' + directory + '/([^/]+)/([^/]+)\\.mdx?$'));
  if (!match) {
    issues.push(filePath + ': chapter file must live under ' + directory + '/<configured-locale>');
    return;
  }
  if (!supportedLocales.includes(match[1])) {
    issues.push(filePath + ': directory locale "' + match[1] + '" is not configured');
    return;
  }
  if (match[1] !== data.locale) {
    issues.push(
      filePath +
        ': directory locale ' +
        match[1] +
        ' does not match metadata locale ' +
        data.locale,
    );
  }
  if (match[2] !== data.chapter_id) {
    issues.push(
      filePath + ': filename must equal chapter_id "' + data.chapter_id + '"',
    );
  }
}

export function validateChapterDocument(
  source,
  {
    sourceName = 'chapter',
    filePath,
    repositoryRoot,
    checkSourceFiles = true,
    supportedLocales = SUPPORTED_LOCALES,
    course,
  } = {},
) {
  const parsed = parseJsonFrontmatter(source, sourceName);
  if (course) supportedLocales = course.activeLocales;
  validateChapterMetadata(parsed.data, sourceName, supportedLocales, { course });
  const issues = [];
  if (/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/.test(source)) {
    issues.push(
      sourceName +
        ': chapter source contains a prohibited control character; preserve formula backslashes as literal source text',
    );
  }
  const learnerProse = renderableMdxSource(parsed.body);

  for (const { label, pattern } of LEARNER_BUILD_META_PATTERNS) {
    if (pattern.test(learnerProse)) {
      issues.push(
        sourceName +
          ': learner-facing prose must not expose ' +
          label +
          '; explain the LLM concept or pedagogical evidence instead',
      );
    }
  }

  if (filePath) {
    validateFileLocation(parsed.data, filePath, issues, supportedLocales, course);
  }

  const markers = extractChapterSectionMarkers(parsed.body);
  const requiredSections = chapterSections(parsed.data, course);
  const acceptedOrder = JSON.stringify(markers) === JSON.stringify(requiredSections) ||
    (!isOrientationChapter(parsed.data) &&
      JSON.stringify(markers) === JSON.stringify(SOLUTION_RUST_CHAPTER_SECTIONS));
  if (!acceptedOrder) {
    issues.push(
      sourceName +
        ': chapter section markers must appear exactly once in this order: ' +
        requiredSections.join(', ') +
        (isOrientationChapter(parsed.data) ? '' : ' (or with rust-implementation immediately before history)'),
    );
  }

  if (acceptedOrder) {
    validateChapterSections(parsed.data, parsed.body, issues, sourceName, course);
  }

  const references = extractRustSourceReferences(renderableMdxSource(parsed.body));
  if (!isOrientationChapter(parsed.data) && references.length === 0) {
    issues.push(sourceName + ': body must include at least one <RustSource> component');
  }
  if (isOrientationChapter(parsed.data) && references.length !== 0) {
    issues.push(sourceName + ': orientation must not include <RustSource> components');
  }

  const declared = new Set(parsed.data.rust_sources.map(sourceIdentity));
  const rendered = new Set();
  references.forEach((reference) => {
    if (!reference.path) {
      issues.push(sourceName + ': every <RustSource> path must be a string literal');
      return;
    }
    if (!isAllowedRustSourcePath(reference.path, course)) {
      issues.push(
        sourceName +
          ': <RustSource> path "' +
          reference.path +
          '" is outside the Rust allowlist',
      );
    }
    if (reference.region !== undefined && !REGION_PATTERN.test(reference.region)) {
      issues.push(
        sourceName +
          ': <RustSource> region "' +
          reference.region +
          '" is not kebab-case',
      );
    }
    if (!hasText(reference.caption)) {
      issues.push(sourceName + ': every <RustSource> caption must be localized literal text');
    }
    if (!hasText(reference.label)) {
      issues.push(sourceName + ': every <RustSource> label must be localized literal text');
    }
    const identity = reference.path + '#' + (reference.region ?? '');
    rendered.add(identity);
    if (!declared.has(identity)) {
      issues.push(
        sourceName +
          ': <RustSource> reference "' +
          identity +
          '" is not declared in rust_sources',
      );
    }
  });

  for (const identity of declared) {
    if (!rendered.has(identity)) {
      issues.push(
        sourceName + ': declared Rust source evidence is not rendered: "' + identity + '"',
      );
    }
  }

  if (repositoryRoot && checkSourceFiles) {
    parsed.data.rust_sources.forEach((declaration) => {
      const absolute = nodePath.resolve(repositoryRoot, declaration.path);
      if (!existsSync(absolute)) {
        issues.push(
          sourceName + ': declared Rust source does not exist: ' + declaration.path,
        );
        return;
      }
      if (declaration.region) {
        try {
          extractRustRegion(
            readFileSync(absolute, 'utf8'),
            declaration.region,
            declaration.path,
          );
        } catch (error) {
          issues.push(...(error.issues ?? [error.message]));
        }
      }
    });
  }

  if (issues.length > 0) {
    throw new ContentValidationError(issues);
  }

  return {
    ...parsed,
    filePath,
    sourceName,
    references,
  };
}

export function sharedChapterData(data) {
  return {
    chapter_id: data.chapter_id,
    order: data.order,
    concept_id: data.concept_id,
    chapter_kind: data.chapter_kind ?? 'lesson',
    formula: data.formula
      ? {
          latex: data.formula.latex,
          symbols: data.formula.symbols.map((symbol) => symbol.symbol),
        }
      : null,
    history_rust_source: data.history.rust_source,
    history_llm_evolution: data.history.llm_evolution
      ? {
          predecessor_kind: data.history.llm_evolution.predecessor_kind,
          sources: data.history.llm_evolution.sources.map((source) => ({
            role: source.role,
            year: source.year,
            name: source.name,
            source_url: source.source_url,
          })),
        }
      : null,
    rust_sources: data.rust_sources.map((source) => ({
      path: source.path,
      region: source.region ?? null,
    })),
    visualization: {
      decision: data.visualization.decision,
      id: data.visualization.id,
      ...(data.visualization.component
        ? { component: data.visualization.component }
        : {}),
      ...((data.visualization.supplementary?.length ?? 0) > 0
        ? {
            supplementary: data.visualization.supplementary.map(
              ({ id, component }) => ({ id, component }),
            ),
          }
        : {}),
    },
  };
}

export function validateChapterLocaleSet(
  documents,
  requiredLocales = SUPPORTED_LOCALES,
  referenceLocale = REFERENCE_LOCALE,
) {
  const issues = [];
  if (
    requiredLocales.length === 0 ||
    new Set(requiredLocales).size !== requiredLocales.length ||
    !requiredLocales.includes(referenceLocale)
  ) {
    issues.push('required locales must be unique and include the reference locale');
  }
  const byLocale = {};
  for (const locale of requiredLocales) {
    const localized = documents.filter((document) => document.data.locale === locale);
    if (localized.length !== 1) {
      issues.push(
        'expected exactly one ' + locale + ' source; found ' + localized.length,
      );
    } else {
      byLocale[locale] = localized[0];
    }
  }
  const unknown = documents.filter(
    (document) => !requiredLocales.includes(document.data.locale),
  );
  if (unknown.length > 0) {
    issues.push(
      'translation set contains locale(s) not active for this chapter: ' +
        [...new Set(unknown.map((document) => document.data.locale))].join(', '),
    );
  }

  const reference = byLocale[referenceLocale];
  if (reference) {
    for (const locale of requiredLocales) {
      const localized = byLocale[locale];
      if (!localized || locale === referenceLocale) continue;
      if (localized.data.chapter_id !== reference.data.chapter_id) {
        issues.push('localized chapter_id values differ');
      }
      if (localized.data.content_revision !== reference.data.content_revision) {
        issues.push(
          reference.data.chapter_id +
            ': ' +
            referenceLocale +
            ' revision ' +
            reference.data.content_revision +
            ' differs from ' +
            locale +
            ' revision ' +
            localized.data.content_revision,
        );
      }
      if (
        JSON.stringify(sharedChapterData(localized.data)) !==
        JSON.stringify(sharedChapterData(reference.data))
      ) {
        issues.push(
          reference.data.chapter_id +
            ': locale-neutral formula, source, LLM-history, visualization, order, or concept fields differ for ' +
            locale,
        );
      }
    }
  }
  if (issues.length > 0) {
    throw new ContentValidationError(
      issues,
      'Localized chapter-set validation failed',
    );
  }
  return {
    chapterId: reference.data.chapter_id,
    revision: reference.data.content_revision,
    reference,
    byLocale: Object.freeze(byLocale),
  };
}

export function findPublishableChapterSets(
  documents,
  localeRequirements = SUPPORTED_LOCALES,
  referenceLocale = REFERENCE_LOCALE,
) {
  const groups = new Map();
  for (const document of documents) {
    const group = groups.get(document.data.chapter_id) ?? [];
    group.push(document);
    groups.set(document.data.chapter_id, group);
  }

  const sets = [];
  for (const [chapterId, group] of groups) {
    const requiredLocales =
      typeof localeRequirements === 'function'
        ? localeRequirements(chapterId)
        : localeRequirements;
    try {
      sets.push(
        validateChapterLocaleSet(group, requiredLocales, referenceLocale),
      );
    } catch {
      // Incomplete, duplicate, stale, or drifting sets are deliberately not publishable.
    }
  }

  return sets.sort(
    (left, right) =>
      left.reference.data.order - right.reference.data.order ||
      left.chapterId.localeCompare(right.chapterId),
  );
}

export function validatePublishedChapterSequence(sets) {
  const ordered = [...sets].sort(
    (left, right) =>
      left.reference.data.order - right.reference.data.order ||
      left.chapterId.localeCompare(right.chapterId),
  );
  const orders = new Set();
  const concepts = new Set();
  const issues = [];
  const firstOrder = ordered[0]?.reference.data.order ?? 1;

  if (firstOrder !== 0 && firstOrder !== 1) {
    issues.push('published chapters must begin at order 0 or 1');
  }

  ordered.forEach((set, index) => {
    const expectedOrder = firstOrder + index;
    const expectedPrefix = String(expectedOrder).padStart(2, '0') + '-';
    const order = set.reference.data.order;
    const concept = set.reference.data.concept_id;
    if (orders.has(order)) {
      issues.push('duplicate published chapter order ' + order);
    }
    if (concepts.has(concept)) {
      issues.push('duplicate published concept_id "' + concept + '"');
    }
    if (order !== expectedOrder || !set.chapterId.startsWith(expectedPrefix)) {
      issues.push(
        set.chapterId +
          ': published chapters must form a contiguous ordered prefix; expected order ' +
          expectedOrder,
      );
    }
    orders.add(order);
    concepts.add(concept);
  });

  if (issues.length > 0) {
    throw new ContentValidationError(issues, 'Published chapter sequence failed');
  }
  return ordered;
}

export function validatePublishedContractSequence(sets, contracts) {
  const orderedSets = validatePublishedChapterSequence(sets);
  const orderedContracts = [...contracts].sort(
    (left, right) =>
      left.data.order - right.data.order ||
      left.data.chapter_id.localeCompare(right.data.chapter_id),
  );
  const issues = [];
  const contractIds = new Set();
  const contractOrders = new Set();
  const contractConcepts = new Set();
  const firstContractOrder = orderedContracts[0]?.data.order ?? 1;

  if (firstContractOrder !== 0 && firstContractOrder !== 1) {
    issues.push('implemented contracts must begin at order 0 or 1');
  }

  orderedContracts.forEach((contract, index) => {
    const data = contract.data;
    if (contractIds.has(data.chapter_id)) {
      issues.push('duplicate implemented contract chapter_id "' + data.chapter_id + '"');
    }
    if (contractOrders.has(data.order)) {
      issues.push('duplicate implemented contract order ' + data.order);
    }
    if (contractConcepts.has(data.concept_id)) {
      issues.push('duplicate implemented contract concept_id "' + data.concept_id + '"');
    }
    if (data.order !== firstContractOrder + index) {
      issues.push(
        data.chapter_id + ': implemented contracts must form a contiguous ordered prefix',
      );
    }
    contractIds.add(data.chapter_id);
    contractOrders.add(data.order);
    contractConcepts.add(data.concept_id);
  });

  if (orderedSets.length !== orderedContracts.length) {
    issues.push(
      'published localized lesson-set count ' +
        orderedSets.length +
        ' differs from implemented contract count ' +
        orderedContracts.length,
    );
  }

  const count = Math.max(orderedSets.length, orderedContracts.length);
  for (let index = 0; index < count; index += 1) {
    const set = orderedSets[index];
    const contract = orderedContracts[index]?.data;
    if (!set || !contract) continue;
    const lessonIdentity = {
      chapter_id: set.chapterId,
      content_revision: set.reference.data.content_revision,
      order: set.reference.data.order,
      concept_id: set.reference.data.concept_id,
    };
    const contractIdentity = {
      chapter_id: contract.chapter_id,
      content_revision: contract.content_revision,
      order: contract.order,
      concept_id: contract.concept_id,
    };
    if (JSON.stringify(lessonIdentity) !== JSON.stringify(contractIdentity)) {
      issues.push(
        'published lesson identity ' +
          JSON.stringify(lessonIdentity) +
          ' differs from implemented contract ' +
          JSON.stringify(contractIdentity),
      );
    }
  }

  if (issues.length > 0) {
    throw new ContentValidationError(issues, 'Published contract sequence failed');
  }
  return orderedSets;
}

function listFiles(directory) {
  if (!existsSync(directory)) return [];
  const files = [];

  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const absolute = nodePath.join(directory, entry.name);
    if (entry.isDirectory()) {
      files.push(...listFiles(absolute));
    } else if (entry.isFile() && /\.mdx?$/.test(entry.name)) {
      files.push(absolute);
    }
  }

  return files.sort();
}

export function readChapterDocuments(
  repositoryRoot,
  supportedLocales = SUPPORTED_LOCALES,
  { course } = {},
) {
  const contentRoot = nodePath.join(repositoryRoot, course?.contentDirectory ?? 'site/src/content/chapters');
  return listFiles(contentRoot).map((filePath) =>
    validateChapterDocument(readFileSync(filePath, 'utf8'), {
      sourceName: nodePath.relative(repositoryRoot, filePath),
      filePath,
      repositoryRoot,
      checkSourceFiles: true,
      supportedLocales,
      course,
    }),
  );
}

export function readChapterContractSummaries(repositoryRoot, { course } = {}) {
  const contractRoot = nodePath.join(repositoryRoot, course?.contractDirectory ?? 'curriculum/chapters');
  if (!existsSync(contractRoot)) return [];
  return readdirSync(contractRoot, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.md'))
    .map((entry) => {
      const filePath = nodePath.join(contractRoot, entry.name);
      return {
        filePath,
        data: parseJsonFrontmatter(
          readFileSync(filePath, 'utf8'),
          nodePath.relative(repositoryRoot, filePath),
        ).data,
      };
    });
}

function messageSchemaKeys(source, sourceName, { name = 'messageKeys', optional = false } = {}) {
  const declaration = source.match(
    new RegExp('export const ' + name + '\\s*=\\s*\\[([\\s\\S]*?)\\]\\s*as const;'),
  );
  if (!declaration) {
    if (optional) return [];
    throw new ContentValidationError([
      sourceName + ': could not find the ' + name + ' schema',
    ]);
  }
  const keys = [...declaration[1].matchAll(/(['"])([A-Za-z][A-Za-z0-9]*)\1/g)].map(
    (match) => match[2],
  );
  if (keys.length === 0 || new Set(keys).size !== keys.length) {
    throw new ContentValidationError([
      sourceName + ': ' + name + ' must contain unique string keys',
    ]);
  }
  return keys;
}

function parseMessageCatalog(source, sourceName) {
  const lexicalKeys = [...source.matchAll(/"((?:\\.|[^"\\])*)"\s*:/g)].map(
    (match) => JSON.parse('"' + match[1] + '"'),
  );
  const issues = [];
  if (new Set(lexicalKeys).size !== lexicalKeys.length) {
    issues.push(sourceName + ': message catalog contains duplicate keys');
  }
  let catalog;
  try {
    catalog = JSON.parse(source);
  } catch (error) {
    issues.push(sourceName + ': invalid JSON: ' + error.message);
  }
  if (catalog !== undefined && !isObject(catalog)) {
    issues.push(sourceName + ': message catalog must be an object');
  }
  if (isObject(catalog)) {
    for (const [key, value] of Object.entries(catalog)) {
      if (!hasText(value)) {
        issues.push(sourceName + ': ' + key + ' must be a non-empty string');
      }
    }
  }
  if (issues.length > 0) throw new ContentValidationError(issues);
  return catalog;
}

export function validateCatalogParity(
  repositoryRoot,
  localeConfiguration = readLocaleConfiguration(repositoryRoot),
) {
  const schemaPath = nodePath.join(
    repositoryRoot,
    'site/src/i18n/messages.ts',
  );
  if (!existsSync(schemaPath)) {
    throw new ContentValidationError([
      'message schema does not exist: ' + schemaPath,
    ]);
  }
  const schema = readFileSync(schemaPath, 'utf8');
  const expected = messageSchemaKeys(schema, schemaPath)
    .sort();
  const optionalCourseGroups = ['COURSE_HOME_MESSAGE_KEYS', 'COURSE_INDEX_MESSAGE_KEYS']
    .map(name => ({ name, keys: messageSchemaKeys(schema, schemaPath, { name, optional: true }) }));
  const optionalCourseKeys = optionalCourseGroups.flatMap(group => group.keys);
  if (new Set([...expected, ...optionalCourseKeys]).size !== expected.length + optionalCourseKeys.length) {
    throw new ContentValidationError(['message schema groups must not overlap']);
  }
  const catalogs = new Map();
  for (const locale of localeConfiguration.locales) {
    const path = nodePath.join(
      repositoryRoot,
      'site/src/i18n/catalogs',
      locale + '.json',
    );
    if (!existsSync(path)) {
      throw new ContentValidationError([
        'configured locale "' + locale + '" is missing catalog ' + path,
      ]);
    }
    catalogs.set(
      locale,
      parseMessageCatalog(readFileSync(path, 'utf8'), path),
    );
  }

  const issues = [];
  for (const [locale, catalog] of catalogs) {
    const actual = Object.keys(catalog).sort();
    const presentCourseKeys = [];
    for (const group of optionalCourseGroups) {
      const present = group.keys.filter(key => Object.hasOwn(catalog, key));
      if (present.length !== 0 && present.length !== group.keys.length) {
        issues.push('message catalog ' + locale + ': optional ' + group.name + ' must be all present or all absent');
      }
      presentCourseKeys.push(...present);
    }
    const expectedForLocale = [...expected, ...presentCourseKeys].sort();
    if (JSON.stringify(actual) !== JSON.stringify(expectedForLocale)) {
      issues.push(
        'message catalog keys differ from the message schema: expected=[' +
          expectedForLocale.join(', ') +
          '], ' +
          locale +
          '=[' +
          actual.join(', ') +
          ']',
      );
    }
  }
  if (issues.length > 0) throw new ContentValidationError(issues);
  return expected.length + optionalCourseKeys.length;
}

function groupsForDocuments(documents) {
  const groups = new Map();
  documents.forEach((document) => {
    const group = groups.get(document.data.chapter_id) ?? [];
    group.push(document);
    groups.set(document.data.chapter_id, group);
  });
  return groups;
}

export function validateAllChapterSets(
  documents,
  {
    requireContiguousPrefix = true,
    requiredLocales = SUPPORTED_LOCALES,
    referenceLocale = REFERENCE_LOCALE,
  } = {},
) {
  const issues = [];
  for (const [chapterId, group] of groupsForDocuments(documents)) {
    const chapterRequiredLocales =
      typeof requiredLocales === 'function'
        ? requiredLocales(chapterId)
        : requiredLocales;
    try {
      validateChapterLocaleSet(
        group,
        chapterRequiredLocales,
        referenceLocale,
      );
    } catch (error) {
      issues.push(
        ...(error.issues ?? [error.message]).map(
          (issue) => chapterId + ': ' + issue,
        ),
      );
    }
  }

  if (issues.length > 0) {
    throw new ContentValidationError(issues, 'Localized publication gate failed');
  }

  const sets = findPublishableChapterSets(
    documents,
    requiredLocales,
    referenceLocale,
  );
  return requireContiguousPrefix
    ? validatePublishedChapterSequence(sets)
    : sets;
}

export function repositoryRootFromCwd(cwd = process.cwd()) {
  const resolved = nodePath.resolve(cwd);
  return nodePath.basename(resolved) === 'site' ? nodePath.dirname(resolved) : resolved;
}

export function validateChapterRouteSource(source, sourceName = 'chapter route') {
  try {
    return validateChapterRouteScope(source, sourceName);
  } catch (error) {
    throw new ContentValidationError(error.issues ?? [error.message]);
  }
}

export function validatePracticalChapterDelegation(source, sourceName = 'practical chapter route') {
  const rendererImport = '../course/[...slug].astro';
  let parsed;
  try {
    parsed = parseAstro(source);
  } catch (error) {
    throw new ContentValidationError([sourceName + ': Astro parser rejected route: ' + error.message]);
  }
  if ((parsed.diagnostics?.length ?? 0) !== 0) {
    throw new ContentValidationError([sourceName + ': Astro route must parse without diagnostics']);
  }
  const nodes = parsed.ast.children.filter(node => node.type !== 'text' || node.value.trim() !== '');
  const frontmatter = nodes[0];
  if (nodes.length !== 2 || frontmatter?.type !== 'frontmatter') {
    throw new ContentValidationError([sourceName + ': practical route must contain only frontmatter and one renderer delegation']);
  }
  const component = nodes[1];
  if (component.type !== 'component' || component.name !== 'CourseChapter' ||
      component.children.length !== 0 || component.attributes.length !== 1 ||
      component.attributes[0].type !== 'attribute' ||
      component.attributes[0].kind !== 'spread' ||
      component.attributes[0].name !== 'Astro.props') {
    throw new ContentValidationError([sourceName + ': practical presentation must be exactly CourseChapter with only the Astro.props spread']);
  }
  const program = ts.createSourceFile(sourceName + '.ts', frontmatter.value,
    ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  if (program.parseDiagnostics.length !== 0) {
    throw new ContentValidationError([sourceName + ': practical frontmatter must parse without diagnostics']);
  }
  const bindingImports = program.statements.filter(node =>
    ts.isImportDeclaration(node) && node.importClause?.name?.text === 'CourseChapter');
  let bindingNames = 0;
  function visit(node) {
    if (ts.isIdentifier(node) && node.text === 'CourseChapter') bindingNames += 1;
    ts.forEachChild(node, visit);
  }
  visit(program);
  const binding = bindingImports[0];
  if (bindingImports.length !== 1 || bindingNames !== 1 ||
      binding.importClause.isTypeOnly || binding.importClause.namedBindings !== undefined ||
      binding.attributes !== undefined || !ts.isStringLiteral(binding.moduleSpecifier) ||
      binding.moduleSpecifier.text !== rendererImport) {
    throw new ContentValidationError([sourceName + ': practical route must bind CourseChapter only through the approved default renderer import']);
  }
  return { rendererImport, componentCount: 1 };
}

export function validateDiagramComponentSource(source, sourceName = 'diagram component') {
  const issues = [];
  try {
    validateDiagramComponentCss(source, sourceName);
  } catch (error) {
    issues.push(...(error.issues ?? [error.message]));
  }
  const figures = source.match(/<figure\b[\s\S]*?>/g) ?? [];
  const registered = figures.filter((tag) => /\bdata-visualization-id\s*=/.test(tag));
  const registrations = source.match(/\bdata-visualization-id\s*=/g) ?? [];
  const captions = source.match(/<figcaption\b/g) ?? [];

  if (figures.length !== 1) {
    issues.push(sourceName + ': useful diagram components must contain exactly one figure');
  }
  if (registered.length !== 1 || registrations.length !== 1) {
    issues.push(
      sourceName + ': the semantic figure must register exactly one data-visualization-id',
    );
  }

  const figure = registered[0] ?? '';
  if (!/\bclass="[^"]*\bcourse-diagram\b[^"]*"/.test(figure)) {
    issues.push(sourceName + ': the registered figure requires the shared course-diagram class');
  }
  if (!/\bdata-diagram-style="course-v1"/.test(figure)) {
    issues.push(sourceName + ': the registered figure requires data-diagram-style="course-v1"');
  }
  for (const attribute of ['tabindex', 'aria-labelledby', 'aria-describedby']) {
    if (!new RegExp('\\b' + attribute + '\\s*=').test(figure)) {
      issues.push(sourceName + ': the registered figure requires ' + attribute);
    }
  }
  if (captions.length !== 1) {
    issues.push(sourceName + ': the registered figure requires exactly one figcaption');
  }

  const figureOffset = source.indexOf(figure);
  const firstFigureChild = source.slice(figureOffset + figure.length);
  if (!/^\s*<figcaption\b/.test(firstFigureChild)) {
    issues.push(sourceName + ': figcaption must remain the registered figure first child');
  }
  const caption = source.match(/<figcaption\b[\s\S]*?<\/figcaption>/)?.[0] ?? '';
  if (!/\bclass="[^"]*\bcourse-diagram__caption\b[^"]*"/.test(caption)) {
    issues.push(sourceName + ': figcaption requires the shared course-diagram__caption role');
  }
  if (!/<h3\b/.test(caption)) {
    issues.push(sourceName + ': the shared caption requires one h3 title');
  }
  if (!/\bclass="[^"]*\bcourse-diagram__description\b[^"]*"/.test(caption)) {
    issues.push(sourceName + ': title and shared learner description must stay inside figcaption');
  }

  const regionTags =
    source.match(/<[a-z][a-z0-9-]*\b[^>]*\brole=(?:"region"|'region')[^>]*>/g) ?? [];
  for (const tag of regionTags) {
    for (const attribute of ['data-diagram-scroll', 'tabindex']) {
      if (!new RegExp('\\b' + attribute + '(?:\\s*=|\\b)').test(tag)) {
        issues.push(sourceName + ': every named diagram region requires ' + attribute);
      }
    }
    if (!/\bclass="[^"]*\bcourse-diagram__scroll\b[^"]*"/.test(tag)) {
      issues.push(sourceName + ': every named diagram region requires course-diagram__scroll');
    }
    if (!/\baria-(?:label|labelledby)\s*=/.test(tag)) {
      issues.push(sourceName + ': every diagram scroll region requires an accessible name');
    }
  }
  const scrollRegistrations = source.match(/\bdata-diagram-scroll\b/g) ?? [];
  if (scrollRegistrations.length !== regionTags.length) {
    issues.push(
      sourceName + ': data-diagram-scroll is reserved for the shared named region boundary',
    );
  }

  const tableTags = source.match(/<table\b[\s\S]*?>/g) ?? [];
  for (const tag of tableTags) {
    if (!/\bdata-diagram-table\b/.test(tag)) {
      issues.push(sourceName + ': every diagram table requires data-diagram-table');
    }
  }
  const articleTags = source.match(/<article\b[\s\S]*?>/g) ?? [];
  for (const tag of articleTags) {
    if (!/\bdata-diagram-card\b/.test(tag) || !/\bdata-diagram-box\b/.test(tag)) {
      issues.push(sourceName + ': every semantic diagram article requires shared card and box roles');
    }
  }

  const privateEnhancementPatterns = [
    ['<script', 'a chapter-local script'],
    ['client:', 'a hydration directive'],
    ['requestFullscreen', 'a private Fullscreen API handler'],
    ['exitFullscreen', 'a private Fullscreen API handler'],
    ['fullscreenchange', 'a private fullscreen event handler'],
    ['cloneNode', 'a duplicated presentation tree'],
    ['data-diagram-full-view-', 'private shared-controller markup'],
    ['<button', 'a private expand control'],
    ['<dialog', 'a private dialog'],
  ];
  for (const [pattern, description] of privateEnhancementPatterns) {
    if (source.includes(pattern)) {
      issues.push(
        sourceName +
          ': diagram components must remain static and use the shared controller, not ' +
          description,
      );
    }
  }

  const privateStylePatterns = [
    [/@media\s*\(\s*max-width\s*:/, 'a viewport-width diagram breakpoint'],
    [/contain\s*:\s*paint\b/, 'paint containment that can hide overflow'],
    [/overflow-x\s*:\s*(?:auto|scroll)\b/, 'a private horizontal-scroll implementation'],
  ];
  for (const [pattern, description] of privateStylePatterns) {
    if (pattern.test(source)) {
      issues.push(sourceName + ': component-local CSS must not define ' + description);
    }
  }

  const rootClasses = figure.match(/\bclass="([^"]*)"/)?.[1]?.split(/\s+/) ?? [];
  const conceptRoot = rootClasses.find((name) => name !== 'course-diagram');
  if (conceptRoot) {
    const escapedRoot = conceptRoot.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const rootRules = source.matchAll(
      new RegExp('\\.' + escapedRoot + '\\s*\\{([^}]*)\\}', 'g'),
    );
    for (const rule of rootRules) {
      if (/overflow\s*:\s*(?:hidden|clip)\b/.test(rule[1])) {
        issues.push(sourceName + ': the semantic diagram frame must not hide or clip overflow');
      }
    }
  }

  if (issues.length > 0) throw new ContentValidationError(issues);
  return { figureCount: figures.length, registeredCount: registered.length };
}

export function validateDiagramComponents(repositoryRoot) {
  const componentDirectory = nodePath.join(
    repositoryRoot,
    'site',
    'src',
    'components',
    'chapters',
  );
  const files = readdirSync(componentDirectory)
    .filter((name) => name.endsWith('Diagram.astro'))
    .sort();
  const issues = [];
  const sharedStylePath = nodePath.join(
    repositoryRoot,
    'site',
    'src',
    'styles',
    'diagram.module.css',
  );
  const globalStylePath = nodePath.join(
    repositoryRoot,
    'site',
    'src',
    'styles',
    'global.css',
  );
  const layoutPath = nodePath.join(
    repositoryRoot,
    'site',
    'src',
    'layouts',
    'BaseLayout.astro',
  );
  if (!existsSync(sharedStylePath)) {
    issues.push('site/src/styles/diagram.module.css: shared diagram module is missing');
  }
  const sharedStyle = existsSync(sharedStylePath) ? readFileSync(sharedStylePath, 'utf8') : '';
  const globalStyle = existsSync(globalStylePath) ? readFileSync(globalStylePath, 'utf8') : '';
  const layout = existsSync(layoutPath) ? readFileSync(layoutPath, 'utf8') : '';
  if (
    !layout.includes("import diagramStyles from '../styles/diagram.module.css';") ||
    !layout.includes('<body class={diagramStyles.host}>')
  ) {
    issues.push('site/src/layouts/BaseLayout.astro: load the shared diagram module exactly once');
  }
  for (const contract of [
    '.host',
    "course-diagram[data-diagram-style='course-v1']",
    'course-diagram__caption',
    'course-diagram__description',
    'course-diagram__scroll',
    'course-diagram__link-separator',
    'data-diagram-card',
    'data-diagram-box',
    'data-diagram-table',
    'state-symbol',
    '--diagram-summary-min',
    '--diagram-cell-padding-inline',
    '--diagram-scroll-inline-size',
    'position: relative',
  ]) {
    if (!sharedStyle.includes(contract)) {
      issues.push('site/src/styles/diagram.module.css: missing shared role ' + contract);
    }
  }
  if (/data-diagram-full-view|figure\[data-visualization-id\]|diagram-full-view-icon/.test(globalStyle)) {
    issues.push('site/src/styles/global.css: diagram presentation belongs in diagram.module.css');
  }

  const sharedDefinitions = new Set(
    [...globalStyle.matchAll(/(--[a-z0-9-]+)\s*:/gi), ...sharedStyle.matchAll(/(--[a-z0-9-]+)\s*:/gi)]
      .map((match) => match[1]),
  );

  for (const file of files) {
    const relative = nodePath.posix.join('site/src/components/chapters', file);
    const source = readFileSync(nodePath.join(componentDirectory, file), 'utf8');
    try {
      validateDiagramComponentSource(source, relative);
    } catch (error) {
      issues.push(...(error.issues ?? [error.message]));
    }
    const definitions = new Set([
      ...sharedDefinitions,
      ...[...source.matchAll(/(--[a-z0-9-]+)\s*:/gi)].map((match) => match[1]),
    ]);
    for (const reference of source.matchAll(/var\(\s*(--[a-z0-9-]+)\s*\)/gi)) {
      if (!definitions.has(reference[1])) {
        issues.push(relative + ': undefined custom property ' + reference[1] + ' needs a fallback');
      }
    }
  }

  if (files.length === 0) issues.push('no chapter diagram components were found');
  if (issues.length > 0) {
    throw new ContentValidationError(issues, 'Diagram presentation gate failed');
  }
  return files.length;
}

export function runContentCheck(args = process.argv.slice(2), cwd = process.cwd()) {
  const repositoryRoot = repositoryRootFromCwd(cwd);
  const { values, positionals } = parseArgs({
    args,
    options: {
      course: { type: 'string', default: FIRST_COURSE_ID },
      chapter: { type: 'string' },
      locale: { type: 'string' },
    },
    strict: true,
    allowPositionals: true,
  });
  if (positionals.length > 1) throw new ContentValidationError(['expected at most one content-check mode']);
  const course = courseById(readCourseConfiguration(repositoryRoot), values.course);
  const mode = positionals[0] ?? 'all';
  const chapter = values.chapter;
  const locale = values.locale;
  const chapterRoutePath = nodePath.join(
    repositoryRoot,
    'site',
    'src',
    'pages',
    '[locale]',
    course.route,
    '[...slug].astro',
  );
  if (!existsSync(chapterRoutePath)) {
    throw new ContentValidationError([
      'site/src/pages/[locale]/' + course.route + '/[...slug].astro: chapter route is missing',
    ]);
  }
  let renderedSourcePath = chapterRoutePath;
  if (isPracticalCourse(course)) {
    const delegation = validatePracticalChapterDelegation(
      readFileSync(chapterRoutePath, 'utf8'), nodePath.relative(repositoryRoot, chapterRoutePath));
    renderedSourcePath = nodePath.resolve(nodePath.dirname(chapterRoutePath), delegation.rendererImport);
    if (!existsSync(renderedSourcePath)) {
      throw new ContentValidationError(['the approved shared course renderer is missing']);
    }
  }
  validateChapterRouteSource(readFileSync(renderedSourcePath, 'utf8'), nodePath.relative(repositoryRoot, renderedSourcePath));
  const localeConfiguration = readLocaleConfiguration(repositoryRoot);
  const registeredLocales = localeConfiguration.locales;
  const referenceLocale = course.referenceLocale;
  const requiredLocales = () => course.activeLocales;
  // The maintained course selector verifies all current private candidates or
  // the current publication chain. Historical40/41 receipts are not consulted.
  if (isPracticalCourse(course)) readPracticalBuildScope(repositoryRoot);
  const catalogCount = validateCatalogParity(repositoryRoot, localeConfiguration);
  const diagramCount = validateDiagramComponents(repositoryRoot);
  const documents = readChapterDocuments(repositoryRoot, course.activeLocales, { course });
  const parityDocuments = documents;

  if (mode === 'chapter') {
    if (!chapter || !registeredLocales.includes(locale)) {
      throw new ContentValidationError([
        'chapter mode requires --locale ' +
          registeredLocales.join('|') +
          ' and --chapter NN-slug',
      ]);
    }
    const activeLocales = requiredLocales(chapter);
    if (!activeLocales.includes(locale)) {
      throw new ContentValidationError([
        'locale ' + locale + ' is registered but not active for chapter ' + chapter,
      ]);
    }
    const selected = documents.filter(
      (document) =>
        document.data.chapter_id === chapter && document.data.locale === locale,
    );
    if (selected.length !== 1) {
      throw new ContentValidationError([
        'expected one source for ' +
          locale +
          '/' +
          chapter +
          '; found ' +
          selected.length,
      ]);
    }
    return {
      mode,
      documents: selected,
      sets: [],
      catalogCount,
      diagramCount,
    };
  }

  if (mode === 'parity') {
    const selected = chapter
      ? parityDocuments.filter((document) => document.data.chapter_id === chapter)
      : parityDocuments;
    if (chapter && selected.length === 0) {
      throw new ContentValidationError(['no sources found for chapter ' + chapter]);
    }
    const sets = validateAllChapterSets(selected, {
      requireContiguousPrefix: !chapter,
      requiredLocales,
      referenceLocale,
    });
    if (!chapter) {
      validatePublishedContractSequence(
        sets,
        readChapterContractSummaries(repositoryRoot, { course }),
      );
    }
    return { mode, documents: selected, sets, catalogCount, diagramCount };
  }

  if (mode !== 'all') {
    throw new ContentValidationError(['unknown content-check mode "' + mode + '"']);
  }

  validateAllChapterSets(parityDocuments, {
    requiredLocales,
    referenceLocale,
  });
  const admittedIds = isPracticalCourse(course)
    ? new Set(practicalPublicationChapterIds(repositoryRoot))
    : null;
  const sets = findPublishableChapterSets(
    admittedIds ? documents.filter(document => admittedIds.has(document.data.chapter_id)) : documents,
    requiredLocales,
    referenceLocale,
  );
  validatePublishedContractSequence(
    sets,
    readChapterContractSummaries(repositoryRoot, { course }),
  );
  return { mode, documents, sets, catalogCount, diagramCount };
}

function isMainModule() {
  return (
    process.argv[1] &&
    nodePath.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
  );
}

if (isMainModule()) {
  try {
    const result = runContentCheck();
    console.log(
      'Content check passed: ' +
        result.documents.length +
        ' localized source(s), ' +
        result.sets.length +
        ' publishable locale set(s), ' +
        result.catalogCount +
        ' catalog key(s), ' +
        result.diagramCount +
        ' shared-full-view diagram component(s).',
    );
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}

