    min-inline-size: 0;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
    padding: 0.7rem 1rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14);
    color: #dce8e2;
    font-size: 0.82rem;
  }

  figcaption > * {
    min-inline-size: 0;
  }

  figcaption span {
    overflow-wrap: anywhere;
  }

  figcaption code {
    max-inline-size: 100%;
