// Read a prepared corpus without choosing how it was retrieved or curated.
//
// JSON Lines is the interchange format: one JSON object per physical line,
// with required string `id` and `text` fields. Other fields remain metadata.
// Serde parses JSON; standard buffered I/O supplies record boundaries. This
// reader does not normalize, filter, deduplicate, split, or approve the text.

use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::BTreeMap;
use std::error::Error;
use std::fmt;
use std::io::{self, BufRead, Read};

/// One document already selected by the corpus-preparation workflow.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
pub struct PreparedDocument {
    pub id: String,
    pub text: String,
    #[serde(flatten)]
    pub metadata: BTreeMap<String, Value>,
}

/// Caller-selected bounds, independent of a dataset name or storage adapter.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ReadLimits {
    /// Maximum bytes in one physical JSON record, including its line ending.
    pub max_record_bytes: usize,
    pub max_documents: u64,
    /// Sum of decoded document text lengths in UTF-8 bytes, not source bytes.
    pub max_total_text_bytes: u64,
}

/// Counts only documents successfully returned to the caller.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Serialize)]
pub struct ReadProgress {
    pub documents: u64,
    pub text_bytes: u64,
}

#[derive(Debug)]
pub enum CorpusReadError {
    InvalidLimits(&'static str),
    Io {
        line: u64,
        source: io::Error,
    },
    RecordTooLarge {
        line: u64,
        limit: usize,
    },
    InvalidJson {
        line: u64,
        source: serde_json::Error,
    },
    EmptyField {
        line: u64,
        field: &'static str,
    },
    TooManyDocuments {
        limit: u64,
    },
    TextBudgetExceeded {
        line: u64,
        limit: u64,
    },
    CountOverflow,
}

impl fmt::Display for CorpusReadError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidLimits(reason) => write!(f, "invalid corpus read limits: {reason}"),
            Self::Io { line, source } => write!(f, "cannot read corpus line {line}: {source}"),
            Self::RecordTooLarge { line, limit } => {
                write!(f, "corpus line {line} exceeds {limit} source bytes")
            }
            Self::InvalidJson { line, source } => {
                write!(f, "invalid document JSON on corpus line {line}: {source}")
            }
            Self::EmptyField { line, field } => {
                write!(f, "corpus line {line} has an empty {field}")
            }
            Self::TooManyDocuments { limit } => {
                write!(f, "corpus exceeds the {limit}-document read limit")
            }
            Self::TextBudgetExceeded { line, limit } => {
                write!(
                    f,
                    "corpus line {line} exceeds the {limit}-byte decoded-text budget"
                )
            }
            Self::CountOverflow => write!(f, "corpus count cannot be represented as u64"),
        }
    }
}

impl Error for CorpusReadError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Io { source, .. } => Some(source),
            Self::InvalidJson { source, .. } => Some(source),
            _ => None,
        }
    }
}

/// A streaming reader over a file, memory buffer, database export, or any other
/// caller-provided buffered byte stream. It holds at most one source record.
///
/// After an error it yields no more documents. Earlier returned documents are
/// not rolled back; a caller needing all-or-nothing publication must stage its
/// own result until end of input. Empty input yields zero documents.
pub struct PreparedCorpusReader<R> {
    reader: R,
    limits: ReadLimits,
    buffer: Vec<u8>,
    progress: ReadProgress,
    finished: bool,
}

impl<R: BufRead> PreparedCorpusReader<R> {
    pub fn new(reader: R, limits: ReadLimits) -> Result<Self, CorpusReadError> {
        if limits.max_record_bytes == 0 || limits.max_record_bytes.checked_add(1).is_none() {
            return Err(CorpusReadError::InvalidLimits(
                "record capacity must be positive with room for one overflow byte",
            ));
        }
        if limits.max_documents == 0 || limits.max_total_text_bytes == 0 {
            return Err(CorpusReadError::InvalidLimits(
                "document and decoded-text capacities must be positive",
            ));
        }
        Ok(Self {
            reader,
            limits,
            buffer: Vec::new(),
            progress: ReadProgress::default(),
            finished: false,
        })
    }

    pub fn progress(&self) -> ReadProgress {
        self.progress
    }

    fn read_document(&mut self) -> Result<Option<PreparedDocument>, CorpusReadError> {
        let line = self
            .progress
            .documents
            .checked_add(1)
            .ok_or(CorpusReadError::CountOverflow)?;
        if self
            .reader
            .fill_buf()
            .map_err(|source| CorpusReadError::Io { line, source })?
            .is_empty()
        {
            return Ok(None);
        }
        if self.progress.documents == self.limits.max_documents {
            return Err(CorpusReadError::TooManyDocuments {
                limit: self.limits.max_documents,
            });
        }

        self.buffer.clear();
        // Standard Take bounds even a malformed record with no newline. The
        // extra byte distinguishes a record at the cap from one over the cap.
        (&mut self.reader)
            .take((self.limits.max_record_bytes + 1) as u64)
            .read_until(b'\n', &mut self.buffer)
            .map_err(|source| CorpusReadError::Io { line, source })?;
        if self.buffer.len() > self.limits.max_record_bytes {
            return Err(CorpusReadError::RecordTooLarge {
                line,
                limit: self.limits.max_record_bytes,
            });
        }

        // region:prepared-document-json
        let document: PreparedDocument = serde_json::from_slice(&self.buffer)
            .map_err(|source| CorpusReadError::InvalidJson { line, source })?;
        for (field, value) in [("id", &document.id), ("text", &document.text)] {
            if value.trim().is_empty() {
                return Err(CorpusReadError::EmptyField { line, field });
            }
        }
        // endregion:prepared-document-json

        let text_bytes = u64::try_from(document.text.len())
            .ok()
            .and_then(|bytes| self.progress.text_bytes.checked_add(bytes))
            .ok_or(CorpusReadError::CountOverflow)?;
        if text_bytes > self.limits.max_total_text_bytes {
            return Err(CorpusReadError::TextBudgetExceeded {
                line,
                limit: self.limits.max_total_text_bytes,
            });
        }
        self.progress = ReadProgress {
            documents: line,
            text_bytes,
        };
        Ok(Some(document))
    }
}

impl<R: BufRead> Iterator for PreparedCorpusReader<R> {
    type Item = Result<PreparedDocument, CorpusReadError>;

    // region:prepared-corpus-stream
    fn next(&mut self) -> Option<Self::Item> {
        if self.finished {
            return None;
        }
        match self.read_document() {
            Ok(Some(document)) => Some(Ok(document)),
            Ok(None) => {
                self.finished = true;
                None
            }
            Err(error) => {
                self.finished = true;
                Some(Err(error))
            }
        }
    }
    // endregion:prepared-corpus-stream
}

impl<R: BufRead> std::iter::FusedIterator for PreparedCorpusReader<R> {}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::{BufReader, Cursor};

    fn limits() -> ReadLimits {
        ReadLimits {
            max_record_bytes: 256,
            max_documents: 10,
            max_total_text_bytes: 1024,
        }
    }

    #[test]
    fn preserves_unicode_escaped_newlines_and_metadata() {
        let source = br#"{"id":"source/7","text":"caf\u00e9\nnext","score":0.5,"origin":{"name":"fixture"}}"#;
        let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
        let document = reader.next().unwrap().unwrap();
        assert_eq!(document.id, "source/7");
        assert_eq!(document.text, "café\nnext");
        assert_eq!(document.metadata["score"], serde_json::json!(0.5));
        assert_eq!(document.metadata["origin"]["name"], "fixture");
        assert_eq!(
            reader.progress(),
            ReadProgress {
                documents: 1,
                text_bytes: 10
            }
        );
        assert!(reader.next().is_none());
    }

    #[test]
    fn accepts_lf_crlf_and_a_final_record_without_newline() {
        let source = b"{\"id\":\"a\",\"text\":\"one\"}\n{\"id\":\"b\",\"text\":\"two\"}\r\n{\"id\":\"c\",\"text\":\"three\"}";
        let documents =
            PreparedCorpusReader::new(BufReader::with_capacity(3, &source[..]), limits())
                .unwrap()
                .collect::<Result<Vec<_>, _>>()
                .unwrap();
        assert_eq!(
            documents
                .iter()
                .map(|document| document.id.as_str())
                .collect::<Vec<_>>(),
            ["a", "b", "c"]
        );
    }

    #[test]
    fn empty_input_is_an_empty_stream() {
        let mut reader = PreparedCorpusReader::new(Cursor::new(b""), limits()).unwrap();
        assert!(reader.next().is_none());
        assert!(reader.next().is_none());
        assert_eq!(reader.progress(), ReadProgress::default());
    }

    #[test]
    fn malformed_record_stops_without_counting_it_or_skipping_forward() {
        let source =
            b"{\"id\":\"a\",\"text\":\"one\"}\nnot-json\n{\"id\":\"b\",\"text\":\"two\"}\n";
        let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
        assert!(reader.next().unwrap().is_ok());
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::InvalidJson { line: 2, .. })
        ));
        assert_eq!(
            reader.progress(),
            ReadProgress {
                documents: 1,
                text_bytes: 3
            }
        );
        assert!(reader.next().is_none());
    }

    #[test]
    fn rejects_blank_lines_invalid_utf8_and_incomplete_schema() {
        for source in [
            &b"\n"[..],
            &b"{\"id\":\"a\",\"text\":\"\xff\"}\n"[..],
            &b"{\"id\":\"a\"}\n"[..],
            &b"{\"id\":1,\"text\":\"one\"}\n"[..],
            &b"{\"id\":\"a\",\"id\":\"b\",\"text\":\"one\"}\n"[..],
            &b"[{\"id\":\"a\",\"text\":\"one\"}]\n"[..],
        ] {
            let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
            assert!(matches!(
                reader.next().unwrap(),
                Err(CorpusReadError::InvalidJson { line: 1, .. })
            ));
            assert!(reader.next().is_none());
        }
    }

    #[test]
    fn required_values_cannot_be_empty_but_text_is_never_trimmed() {
        for (source, field) in [
            (r#"{"id":" ","text":"one"}"#, "id"),
            (r#"{"id":"a","text":"\n\t"}"#, "text"),
        ] {
            let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
            assert!(
                matches!(reader.next().unwrap(), Err(CorpusReadError::EmptyField { field: actual, .. }) if actual == field)
            );
        }
        let mut reader =
            PreparedCorpusReader::new(Cursor::new(r#"{"id":"a","text":" one \n"}"#), limits())
                .unwrap();
        assert_eq!(reader.next().unwrap().unwrap().text, " one \n");
    }

    #[test]
    fn record_bound_is_exact_and_includes_the_line_ending() {
        let source = b"{\"id\":\"a\",\"text\":\"one\"}\n";
        let exact = ReadLimits {
            max_record_bytes: source.len(),
            ..limits()
        };
        assert!(
            PreparedCorpusReader::new(Cursor::new(source), exact)
                .unwrap()
                .next()
                .unwrap()
                .is_ok()
        );
        let short = ReadLimits {
            max_record_bytes: source.len() - 1,
            ..limits()
        };
        let mut reader = PreparedCorpusReader::new(Cursor::new(source), short).unwrap();
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::RecordTooLarge { line: 1, .. })
        ));
        assert_eq!(reader.progress(), ReadProgress::default());
        assert!(reader.next().is_none());
    }

    #[test]
    fn bounds_an_unterminated_oversized_record_before_json_parsing() {
        let source = vec![b'x'; 4096];
        let mut reader = PreparedCorpusReader::new(Cursor::new(source), limits()).unwrap();
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::RecordTooLarge {
                line: 1,
                limit: 256
            })
        ));
        assert_eq!(reader.buffer.len(), 257);
    }

    #[test]
    fn document_and_text_limits_do_not_count_a_failed_document() {
        let source = b"{\"id\":\"a\",\"text\":\"one\"}\n{\"id\":\"b\",\"text\":\"two\"}\n";
        let mut reader = PreparedCorpusReader::new(
            Cursor::new(source),
            ReadLimits {
                max_documents: 1,
                ..limits()
            },
        )
        .unwrap();
        assert!(reader.next().unwrap().is_ok());
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::TooManyDocuments { limit: 1 })
        ));
        assert_eq!(
            reader.progress(),
            ReadProgress {
                documents: 1,
                text_bytes: 3
            }
        );

        let mut reader = PreparedCorpusReader::new(
            Cursor::new(source),
            ReadLimits {
                max_total_text_bytes: 5,
                ..limits()
            },
        )
        .unwrap();
        assert!(reader.next().unwrap().is_ok());
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::TextBudgetExceeded { line: 2, limit: 5 })
        ));
        assert_eq!(
            reader.progress(),
            ReadProgress {
                documents: 1,
                text_bytes: 3
            }
        );
        assert!(reader.next().is_none());
    }

    #[test]
    fn exact_document_and_text_caps_still_allow_end_of_input() {
        let source = b"{\"id\":\"a\",\"text\":\"one\"}\n";
        let mut reader = PreparedCorpusReader::new(
            Cursor::new(source),
            ReadLimits {
                max_documents: 1,
                max_total_text_bytes: 3,
                ..limits()
            },
        )
        .unwrap();
        assert!(reader.next().unwrap().is_ok());
        assert!(reader.next().is_none());
    }

    struct BrokenRead;

    impl Read for BrokenRead {
        fn read(&mut self, _: &mut [u8]) -> io::Result<usize> {
            Err(io::Error::other("injected read failure"))
        }
    }

    #[test]
    fn io_error_is_not_end_of_input() {
        let mut reader = PreparedCorpusReader::new(BufReader::new(BrokenRead), limits()).unwrap();
        assert!(matches!(
            reader.next().unwrap(),
            Err(CorpusReadError::Io { line: 1, .. })
        ));
        assert!(reader.next().is_none());
        assert_eq!(reader.progress(), ReadProgress::default());
    }

    // region:loading-is-not-preparation
    #[test]
    fn loader_does_not_curate_repeated_ids_or_text() {
        let source =
            b"{\"id\":\"same\",\"text\":\"same text\"}\n{\"id\":\"same\",\"text\":\"same text\"}\n";
        let documents = PreparedCorpusReader::new(Cursor::new(source), limits())
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(documents.len(), 2);
        assert_eq!(documents[0], documents[1]);
    }
    // endregion:loading-is-not-preparation

    #[test]
    fn invalid_limits_are_rejected_before_reading() {
        for bad in [
            ReadLimits {
                max_record_bytes: 0,
                ..limits()
            },
            ReadLimits {
                max_record_bytes: usize::MAX,
                ..limits()
            },
            ReadLimits {
                max_documents: 0,
                ..limits()
            },
            ReadLimits {
                max_total_text_bytes: 0,
                ..limits()
            },
        ] {
            assert!(matches!(
                PreparedCorpusReader::new(BufReader::new(BrokenRead), bad),
                Err(CorpusReadError::InvalidLimits(_))
            ));
        }
    }
}

// A scope-bearing projection of the existing scalar experiment. This module
// changes no tokenizer, decoder, training, evaluation or generation algorithm.

use std::error::Error;
use std::fmt;
use std::path::Path;

use llm_from_scratch::pipeline::{CapstoneConfig, CapstoneRun, PipelineError, run_capstone};
use llm_from_scratch_practical::artifact_identity::{
    ArtifactDigest, ArtifactIdentity, IdentityError, sha256,
};
use llm_from_scratch_practical::reference_source_identity::ReferenceSourceProof;

pub const CORPUS_SHA256: &str = "8fcb3e8d0109f14b2007cfbeb375db6b7886ada8f7104b1eea53f929f8bcd293";
pub const SPLITS_SHA256: &str = "52f074ee41b8714763c6ba1c47fbf91e1ab8f51c35a328a8d0aecd551cc95f52";
pub const SUCCESSOR_CHAPTER: &str = "02-corpus-preparation";

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ReferenceHandoffError {
    Identity(IdentityError),
    FixtureMismatch(&'static str),
    Pipeline(PipelineError),
    Invariant(&'static str),
    Serialization,
}

impl fmt::Display for ReferenceHandoffError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Identity(error) => error.fmt(formatter),
            Self::FixtureMismatch(which) => {
                write!(formatter, "reference fixture mismatch: {which}")
            }
            Self::Pipeline(error) => error.fmt(formatter),
            Self::Invariant(message) => formatter.write_str(message),
            Self::Serialization => formatter.write_str("reference report serialization failed"),
        }
    }
}

impl Error for ReferenceHandoffError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Identity(error) => Some(error),
            Self::Pipeline(error) => Some(error),
            _ => None,
        }
    }
}

impl From<IdentityError> for ReferenceHandoffError {
    fn from(error: IdentityError) -> Self {
        Self::Identity(error)
    }
}

impl From<PipelineError> for ReferenceHandoffError {
    fn from(error: PipelineError) -> Self {
        Self::Pipeline(error)
    }
}

fn canonical_string(identity: &ArtifactIdentity) -> Result<String, IdentityError> {
    String::from_utf8(identity.canonical_bytes()?).map_err(|_| IdentityError::Serialization)
}

// region:reference-input-identity
/// Bind every tiny-config field, including exact represented floating values.
/// The count is the reference decoder's required 1,188-parameter invariant.
pub fn tiny_config_identity() -> Result<ArtifactIdentity, IdentityError> {
    let config = CapstoneConfig::tiny();
    let fields = [
        ("parameters", "1188".to_owned()),
        ("bpe_merges", config.bpe_merges().to_string()),
        ("model_width", config.model_width().to_string()),
        ("heads", config.heads().to_string()),
        (
            "feed_forward_width",
            config.feed_forward_width().to_string(),
        ),
        ("layers", config.layers().to_string()),
        ("context_length", config.context_length().to_string()),
        ("window_stride", config.window_stride().to_string()),
        ("update_batch_size", config.update_batch_size().to_string()),
        (
            "evaluation_batch_size",
            config.evaluation_batch_size().to_string(),
        ),
        ("updates", config.updates().to_string()),
        (
            "learning_rate_f64_bits",
            format!("{:016x}", config.learning_rate().to_bits()),
        ),
        (
            "max_gradient_norm_f64_bits",
            format!("{:016x}", config.max_gradient_norm().to_bits()),
        ),
        ("seed", config.seed().to_string()),
        ("generation_seed", config.generation_seed().to_string()),
        (
            "bigram_alpha_f64_bits",
            format!("{:016x}", config.bigram_alpha().to_bits()),
        ),
        (
            "generation_temperature_f64_bits",
            format!("{:016x}", config.generation_temperature().to_bits()),
        ),
        ("generation_top_k", config.generation_top_k().to_string()),
        ("generation_tokens", config.generation_tokens().to_string()),
    ];
    ArtifactIdentity::new(
        "scalar_reference_config",
        fields.iter().map(|(key, value)| (*key, value.as_str())),
    )
}

/// Pure identity construction, also usable by mutation tests without training.
/// An identity by itself does not admit alternate inputs to the reference run.
pub fn reference_input_identity(
    config: &ArtifactIdentity,
    corpus: &[u8],
    splits: &[u8],
    source: &ArtifactIdentity,
) -> Result<ArtifactIdentity, IdentityError> {
    let corpus_digest = sha256(corpus);
    let splits_digest = sha256(splits);
    let fixture = ArtifactIdentity::new(
        "scalar_reference_fixture",
        [
            ("corpus_sha256", corpus_digest.as_hex()),
            ("splits_sha256", splits_digest.as_hex()),
        ],
    )?;
    let config_bytes = canonical_string(config)?;
    let fixture_bytes = canonical_string(&fixture)?;
    let source_bytes = canonical_string(source)?;
    ArtifactIdentity::new(
        "scalar_reference_run",
        [
            ("config_1188", config_bytes.as_str()),
            ("fixture", fixture_bytes.as_str()),
            ("source_revision", source_bytes.as_str()),
        ],
    )
}
// endregion:reference-input-identity

#[derive(Clone, Debug, PartialEq)]
pub struct ReferenceHandoffTrace {
    identity: ArtifactIdentity,
    digest: ArtifactDigest,
    source_revision: String,
    observation: CapstoneRun,
}

impl ReferenceHandoffTrace {
    pub fn identity(&self) -> &ArtifactIdentity {
        &self.identity
    }
    pub fn digest(&self) -> &ArtifactDigest {
        &self.digest
    }
    pub fn source_revision(&self) -> &str {
        &self.source_revision
    }
    pub fn observation(&self) -> &CapstoneRun {
        &self.observation
    }

    // region:scope-bearing-report
    /// Read structured evidence from this one observation; never parse stdout
    /// or run another model to produce either reporting projection.
    pub fn report(&self) -> Result<String, ReferenceHandoffError> {
        let run = &self.observation;
        let evaluation = run.final_evaluation();
        let checkpoint = run.checkpoint();
        let generation = run.generation();
        let config = CapstoneConfig::tiny();
        let targets_per_schedule =
            config.updates() * config.update_batch_size() * config.context_length();
        let record = serde_json::json!({
            "schema_version": 1,
            "chapter": "01-reference-core-handoff",
            "reference_identity": self.digest.as_hex(),
            "source_revision": self.source_revision,
            "scope": "scalar-reference-fixed-fixture-regression",
            "documents": {
                "train": run.partitions().train_document_ids().len(),
                "validation": run.partitions().validation_document_ids().len(),
                "test": run.partitions().test_document_ids().len()
            },
            "model": { "parameters": run.training().parameter_count(), "context_tokens": config.context_length() },
            "training": {
                "target_count_basis": "derived-from-frozen-full-batch-schedules",
                "updates_per_schedule": config.updates(),
                "independent_schedules": 2,
                "valid_targets_per_schedule": targets_per_schedule,
                "valid_targets_primary_plus_replay": 2 * targets_per_schedule,
                "selected_step": run.training().selected_step(),
                "within_invocation_replay_bitwise": run.training().replay_bitwise()
            },
            "evaluation": {
                "unit": "overlapping-window-target-slot",
                "windows": evaluation.window_count(),
                "window_target_slots": evaluation.window_target_slot_count(),
                "document_transition_occurrences": evaluation.document_transition_occurrence_count(),
                "transition_multiplicity_counts": evaluation.transition_multiplicity_counts(),
                "decoder_mean_nll_nats_per_slot": evaluation.decoder().mean_nll(),
                "bigram_mean_nll_nats_per_slot": evaluation.bigram().mean_nll(),
                "once_per_transition_metric_reported": false,
                "independent_generalization_estimate": false
            },
            "checkpoint": {
                "bytes_roundtrip": checkpoint.bytes_roundtrip(),
                "model_bits_exact": checkpoint.model_bits_exact(),
                "optimizer_bits_exact": checkpoint.optimizer_bits_exact(),
                "tokenizer_exact": checkpoint.tokenizer_exact(),
                "logit_probe_text": checkpoint.logit_probe_text(),
                "logit_probe_ids": checkpoint.logit_probe_ids(),
                "probe_logits_bitwise": checkpoint.prompt_logits_bitwise(),
                "complete_job_resume_established": false
            },
            "generation": {
                "prompt": generation.prompt_text(),
                "token_ids": generation.generated_ids(),
                "decoded_text": generation.decoded_text(),
                "cached_reference_tokens_exact": generation.tokens_exact(),
                "cached_reference_decisions_bitwise": generation.decisions_bitwise(),
                "cached_reference_rng_exact": generation.rng_state_exact(),
                "useful_language_quality_established": false
            },
            "laptop_throughput_measured": false,
            "successor_chapter": SUCCESSOR_CHAPTER
        });
        let mut text = serde_json::to_string_pretty(&record)
            .map_err(|_| ReferenceHandoffError::Serialization)?;
        text.push('\n');
        Ok(text)
    }
    // endregion:scope-bearing-report
}

// region:reference-handoff
/// Refuse changed fixtures before model/checkpoint work, then call the existing
/// capstone once. That call already includes primary training and full replay.
pub fn run_reference_handoff(
    corpus_source: &str,
    split_source: &str,
    checkpoint_path: impl AsRef<Path>,
    source: &ReferenceSourceProof,
) -> Result<ReferenceHandoffTrace, ReferenceHandoffError> {
    if sha256(corpus_source.as_bytes()).as_hex() != CORPUS_SHA256 {
        return Err(ReferenceHandoffError::FixtureMismatch("corpus"));
    }
    if sha256(split_source.as_bytes()).as_hex() != SPLITS_SHA256 {
        return Err(ReferenceHandoffError::FixtureMismatch("split manifest"));
    }
    // Safe callers obtain this opaque proof only through the foundation's
    // approved-manifest/compiled-census verification, not a revision string.
    let identity = reference_input_identity(
        &tiny_config_identity()?,
        corpus_source.as_bytes(),
        split_source.as_bytes(),
        source.identity(),
    )?;
    let digest = identity.digest()?;
    let observation = run_capstone(
        corpus_source,
        split_source,
        checkpoint_path,
        CapstoneConfig::tiny(),
    )?;
    let evaluation = observation.final_evaluation();
    let checkpoint = observation.checkpoint();
    if observation.training().parameter_count() != 1188
        || observation.training().optimizer_step() != 32
        || !observation.training().replay_bitwise()
        || evaluation.window_count() != 436
        || evaluation.window_target_slot_count() != 1744
        || evaluation.document_transition_occurrence_count() != 442
        || !evaluation.decoder().mean_nll().is_finite()
        || !evaluation.bigram().mean_nll().is_finite()
        || !checkpoint.bytes_roundtrip()
        || !checkpoint.model_bits_exact()
        || !checkpoint.optimizer_bits_exact()
        || !checkpoint.tokenizer_exact()
        || !checkpoint.prompt_logits_bitwise()
        || !observation.generation().tokens_exact()
        || !observation.generation().decisions_bitwise()
        || !observation.generation().rng_state_exact()
    {
        return Err(ReferenceHandoffError::Invariant(
            "scalar reference handoff evidence changed",
        ));
    }
    Ok(ReferenceHandoffTrace {
        identity,
        digest,
        source_revision: source.source_revision().to_owned(),
        observation,
    })
}
// endregion:reference-handoff

