    let source = verify_compiled_reference_source()?;
    let checkpoint = OwnedCheckpoint::new()?;
    let trace = run_reference_handoff(CORPUS, SPLITS, &checkpoint.file, &source)?;
    print!("{}", trace.report()?);
    Ok(())
}
